window.PK=window.PK||{};window.PK.glossar=[{"slug":"5-amino-1mq","begriff":"5-Amino-1MQ","begriff_en":"5-Amino-1MQ","kategorie":"wirkstoff","kurz":"Molecola piccola investigata come inibitore NNMT in modelli preclinici. Non è un peptide.","kurz_en":"Molecola piccola investigata come inibitore NNMT in modelli preclinici. Non è un peptide.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 29155147","titel_en":"PubMed: Pubblicazione di ricerca, PMID 29155147","url":"https://pubmed.ncbi.nlm.nih.gov/29155147/"}],"text":"Il paper originale collegato investiga inibitori NNMT di piccole molecole in saggi cellulari e un modello di obesità indotta da dieta in topi. Non fornisce evidenze cliniche per l'uso dei prodotti shop.","text_en":"Il paper originale collegato investiga inibitori NNMT di piccole molecole in saggi cellulari e un modello di obesità indotta da dieta in topi. Non fornisce evidenze cliniche per l'uso dei prodotti shop.","synonyme":["5-Amino 1MQ","5A1MQ","Inibitore NNMT"],"synonyme_en":["5-Amino 1MQ","5A1MQ","Inibitore NNMT"],"link":"wirkstoffe/5-amino-1mq.html"},{"slug":"affiliate-link","begriff":"Link affiliato","begriff_en":"Link affiliato","kategorie":"vergleich","kurz":"Un link affiliato porta a un negozio esterno e può innescare una commissione su un acquisto.","kurz_en":"Un link affiliato porta a un negozio esterno e può innescare una commissione su un acquisto.","quellen":[{"titel":"Peptide Compass: La nostra dichiarazione affiliata","titel_en":"Peptide Compass: La nostra dichiarazione affiliata","url":"https://peptidkompass.com/it/affiliate-hinweis.html"}],"text":"I link affiliati portano un'etichetta Pubblicità direttamente al link e utilizzano inoltre l'attributo nofollow sponsorizzato. L'etichetta si applica anche ai link al negozio senza una partnership confermata. Lo stato di partner e una possibile commissione non cambiano il modo in cui un fornitore viene valutato.","text_en":"I link affiliati portano un'etichetta Pubblicità direttamente al link e utilizzano inoltre l'attributo nofollow sponsorizzato. L'etichetta si applica anche ai link al negozio senza una partnership confermata. Lo stato di partner e una possibile commissione non cambiano il modo in cui un fornitore viene valutato.","siehe":["partnercode"],"seiten":["affiliate-hinweis.html"]},{"slug":"agonist","begriff":"Agonista","begriff_en":"Agonista","kategorie":"grundlagen","kurz":"Una molecola che si lega a un recettore e innesca la sua catena di segnalazione. Opposto: antagonista.","kurz_en":"Una molecola che si lega a un recettore e innesca la sua catena di segnalazione. Opposto: antagonista.","quellen":[{"titel":"NCI: agonista","titel_en":"NCI: agonista","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/agonist"}],"text":"Un agonista si lega a un recettore e attiva la catena di segnalazione collegata ad esso, simile a una chiave che apre una serratura. Il corrispondente è un antagonista: si lega anche al recettore ma non innesca una catena di segnalazione, occupando invece il sito e bloccando un agonista dal legarsi. Gli studi utilizzano entrambi i ruoli per sondare le vie di segnalazione dei recettori in modo mirato.","text_en":"Un agonista si lega a un recettore e attiva la catena di segnalazione collegata ad esso, simile a una chiave che apre una serratura. Il corrispondente è un antagonista: si lega anche al recettore ma non innesca una catena di segnalazione, occupando invece il sito e bloccando un agonista dal legarsi. Gli studi utilizzano entrambi i ruoli per sondare le vie di segnalazione dei recettori in modo mirato.","siehe":["rezeptor","analogon"]},{"slug":"aliquot","begriff":"Aliquot","begriff_en":"Aliquot","kategorie":"handhabung","kurz":"Un aliquot è una piccola porzione misurata prelevata da una soluzione di laboratorio più grande, solitamente conservata separatamente.","kurz_en":"Un aliquot è una piccola porzione misurata prelevata da una soluzione di laboratorio più grande, solitamente conservata separatamente.","quellen":[{"titel":"Hoofnagle et al. (2016): Analisi dei peptidi e manipolazione in laboratorio","titel_en":"Hoofnagle et al. (2016): Analisi dei peptidi e manipolazione in laboratorio","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"Un aliquot è una porzione di campione separata. Le porzioni separate possono evitare cicli di temperatura ripetuti dell'intero stock.","text_en":"Un aliquot è una porzione di campione separata. Le porzioni separate possono evitare cicli di temperatura ripetuti dell'intero stock.","siehe":["vial","konzentration","sterilitaet"]},{"slug":"aminosaeure","begriff":"Amminoacido","begriff_en":"Amminoacido","kategorie":"grundlagen","kurz":"Il blocco costruttivo di base da cui i peptidi e le proteine sono assemblati tramite legami peptidici.","kurz_en":"Il blocco costruttivo di base da cui i peptidi e le proteine sono assemblati tramite legami peptidici.","quellen":[{"titel":"NCI: amminoacido","titel_en":"NCI: amminoacido","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/amino-acid"}],"text":"Gli amminoacidi contengono un gruppo amminico e un gruppo carbossilico. Le proteine sono comunemente descritte utilizzando 20 amminoacidi standard. I legami peptidici li uniscono in catene; il loro ordine è chiamato sequenza.","text_en":"Gli amminoacidi contengono un gruppo amminico e un gruppo carbossilico. Le proteine sono comunemente descritte utilizzando 20 amminoacidi standard. I legami peptidici li uniscono in catene; il loro ordine è chiamato sequenza.","synonyme":["Amminoacidi"],"synonyme_en":["Amminoacidi"],"siehe":["peptid","peptidbindung","sequenz"],"seiten":["peptid-1x1.html"]},{"slug":"analogon","begriff":"Analogo","begriff_en":"Analogo","kategorie":"grundlagen","kurz":"Una variante sintetizzata di un peptide endogeno con una struttura leggermente alterata.","kurz_en":"Una variante sintetizzata di un peptide endogeno con una struttura leggermente alterata.","quellen":[{"titel":"EMA: Semaglutide come analogo del GLP-1","titel_en":"EMA: Semaglutide come analogo del GLP-1","url":"https://www.ema.europa.eu/en/medicines/human/EPAR/ozempic"}],"text":"Un analogo è una variante prodotta in laboratorio di un peptide naturale in cui singoli amminoacidi sono stati scambiati, aggiunti o rimossi. I ricercatori utilizzano tali modifiche strutturali per studiare proprietà come stabilità o comportamento di legame al recettore in modo mirato. Un esempio è il semaglutide, un analogo dell'ormone endogeno GLP-1.","text_en":"Un analogo è una variante prodotta in laboratorio di un peptide naturale in cui singoli amminoacidi sono stati scambiati, aggiunti o rimossi. I ricercatori utilizzano tali modifiche strutturali per studiare proprietà come stabilità o comportamento di legame al recettore in modo mirato. Un esempio è il semaglutide, un analogo dell'ormone endogeno GLP-1.","synonyme":["Analoghi"],"synonyme_en":["Analoghi"],"siehe":["peptid","fragment","agonist"]},{"slug":"antimikrobielles-peptid","begriff":"Peptidi antimicrobici","begriff_en":"Peptidi antimicrobici","kategorie":"klassen","kurz":"I peptidi antimicrobici fanno parte della difesa immunitaria innata, prodotti nella pelle e nelle membrane mucose.","kurz_en":"I peptidi antimicrobici fanno parte della difesa immunitaria innata, prodotti nella pelle e nelle membrane mucose.","quellen":[{"titel":"NCBI Bookshelf: Sistema immunitario innato","titel_en":"NCBI Bookshelf: Sistema immunitario innato","url":"https://www.ncbi.nlm.nih.gov/books/NBK459455/"}],"text":"I peptidi antimicrobici, anche chiamati AMP o peptidi di difesa dell'ospite, fanno parte della difesa immunitaria innata. Sono prodotti dalle cellule della pelle e mucose nonché dalle cellule immunitarie e si inseriscono nelle membrane di batteri, funghi o virus. Il gruppo umano meglio conosciuto è le catelicidine, la cui unica forma attiva umana è la LL-37. Oltre a questo meccanismo diretto di membrana, gli AMP sono anche studiati come molecole di segnalazione del sistema immunitario.","text_en":"I peptidi antimicrobici, anche chiamati AMP o peptidi di difesa dell'ospite, fanno parte della difesa immunitaria innata. Sono prodotti dalle cellule della pelle e mucose nonché dalle cellule immunitarie e si inseriscono nelle membrane di batteri, funghi o virus. Il gruppo umano meglio conosciuto è le catelicidine, la cui unica forma attiva umana è la LL-37. Oltre a questo meccanismo diretto di membrana, gli AMP sono anche studiati come molecole di segnalazione del sistema immunitario.","synonyme":["AMP","Peptidi di difesa dell'ospite"],"synonyme_en":["AMP","Peptidi di difesa dell'ospite"],"siehe":["protein","peptid"],"wirkstoffe":["ll-37"],"seiten":["peptid-1x1.html"]},{"slug":"aod-9604","begriff":"AOD-9604","begriff_en":"AOD-9604","kategorie":"wirkstoff","kurz":"Frammento di ormone della crescita modificato investigato in studi metabolici.","kurz_en":"Frammento di ormone della crescita modificato investigato in studi metabolici.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 11146367","titel_en":"PubMed: Pubblicazione di ricerca, PMID 11146367","url":"https://pubmed.ncbi.nlm.nih.gov/11146367/"}],"text":"Il paper originale citato investiga l'AOD-9604 nei ratti Zucker. I risultati da questo modello animale non possono essere trasferiti direttamente agli esseri umani o ai prodotti venduti dai fornitori di ricerca.","text_en":"Il paper originale citato investiga l'AOD-9604 nei ratti Zucker. I risultati da questo modello animale non possono essere trasferiti direttamente agli esseri umani o ai prodotti venduti dai fornitori di ricerca.","synonyme":["Farmaco anti-obesità 9604","Tyr-hGH Frag 177-191"],"synonyme_en":["Farmaco anti-obesità 9604","Tyr-hGH Frag 177-191"],"link":"wirkstoffe/aod-9604.html"},{"slug":"arzneimittel","begriff":"Prodotto medicinale","begriff_en":"Prodotto medicinale","kategorie":"recht","kurz":"Un prodotto medicinale è legalmente definito come una sostanza destinata a trattare o prevenire malattie negli esseri umani.","kurz_en":"Un prodotto medicinale è legalmente definito come una sostanza destinata a trattare o prevenire malattie negli esseri umani.","quellen":[{"titel":"Legge sui medicinali tedesca, sezione 2: Definizione di medicinali","titel_en":"Legge sui medicinali tedesca, sezione 2: Definizione di medicinali","url":"https://www.gesetze-im-internet.de/amg_1976/__2.html"}],"text":"La sezione 2 della Legge sui medicinali tedesca copre sostanze in base al loro uso previsto correlato alla malattia e a determinate funzioni farmacologiche, immunologiche o metaboliche. La classificazione è distinta dall'autorizzazione all'immissione in commercio. Un'etichetta RUO non esclude automaticamente lo status di prodotto medicinale.","text_en":"La sezione 2 della Legge sui medicinali tedesca copre sostanze in base al loro uso previsto correlato alla malattia e a determinate funzioni farmacologiche, immunologiche o metaboliche. La classificazione è distinta dall'autorizzazione all'immissione in commercio. Un'etichetta RUO non esclude automaticamente lo status di prodotto medicinale.","synonyme":["Medicina"],"synonyme_en":["Medicina"],"siehe":["ruo","zulassung","rezeptpflicht"],"seiten":["peptid-1x1.html"]},{"slug":"association","begriff":"Associazione (vs. causalità)","begriff_en":"Associazione (vs. causalità)","kategorie":"studien","kurz":"Due cose si verificano insieme. Questo da solo non dimostra che l'una causi l'altra.","kurz_en":"Due cose si verificano insieme. Questo da solo non dimostra che l'una causi l'altra.","quellen":[{"titel":"NLM MeSH: Causality","titel_en":"NLM MeSH: Causality","url":"https://www.ncbi.nlm.nih.gov/mesh/68015984"}],"text":"Un'associazione significa che due caratteristiche compaiono insieme dal punto di vista statistico, ad esempio un'abitudine e un esito di salute. Causalità significa che una produce l'altra. Gli studi osservazionali di solito mostrano solo associazioni, perché fattori di confondimento, direzione inversa o caso possono spiegare il legame. Per stabilire causa ed effetto servono prove aggiuntive, come gli studi randomizzati.","text_en":"Un'associazione significa che due caratteristiche compaiono insieme dal punto di vista statistico, ad esempio un'abitudine e un esito di salute. Causalità significa che una produce l'altra. Gli studi osservazionali di solito mostrano solo associazioni, perché fattori di confondimento, direzione inversa o caso possono spiegare il legame. Per stabilire causa ed effetto servono prove aggiuntive, come gli studi randomizzati.","synonyme":["Correlazione","Causalità"],"synonyme_en":["Correlazione","Causalità"],"siehe":["confounder","observational-study","rct"],"seiten":["studien.html"]},{"slug":"bakteriostatisches-wasser","begriff":"Acqua batteriostatica","begriff_en":"Acqua batteriostatica","kategorie":"handhabung","kurz":"L'acqua batteriostatica è acqua sterile con un conservante, solitamente alcool benzilico, per soluzioni utilizzate più di una volta.","kurz_en":"L'acqua batteriostatica è acqua sterile con un conservante, solitamente alcool benzilico, per soluzioni utilizzate più di una volta.","quellen":[{"titel":"DailyMed: Acqua batteriostatica, composizione","titel_en":"DailyMed: Acqua batteriostatica, composizione","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=87d6e9dc-fe3b-4593-ac9a-d7493d1959c7"}],"text":"Batteriostatico significa che la crescita batterica è inibita. La composizione è specifica del prodotto; le preparazioni medicinali possono contenere alcool benzilico. Questa descrizione non verifica né la compatibilità con un peptide particolare né la sicurezza di un prodotto commerciale.","text_en":"Batteriostatico significa che la crescita batterica è inibita. La composizione è specifica del prodotto; le preparazioni medicinali possono contenere alcool benzilico. Questa descrizione non verifica né la compatibilità con un peptide particolare né la sicurezza di un prodotto commerciale.","synonyme":["acqua BAC"],"synonyme_en":["acqua BAC"],"siehe":["steriles-wasser","rekonstitution","sterilitaet"]},{"slug":"observational-study","begriff":"Studio osservazionale","begriff_en":"Studio osservazionale","kategorie":"studien","kurz":"Studio in cui le persone vengono solo osservate o si misurano gli esiti, senza alcun intervento come un trattamento.","kurz_en":"Studio in cui le persone vengono solo osservate o si misurano gli esiti, senza alcun intervento come un trattamento.","quellen":[{"titel":"NCI: studio osservazionale","titel_en":"NCI: studio osservazionale","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/observational-study"}],"text":"In uno studio osservazionale le persone vengono osservate o si misurano gli esiti senza che i ricercatori cerchino di influenzare il risultato, ad esempio con un trattamento. Gli studi di coorte ne sono un esempio. Poiché i gruppi non sono assegnati in modo casuale, gli studi osservazionali possono mostrare associazioni ma non possono dimostrare una causa.","text_en":"In uno studio osservazionale le persone vengono osservate o si misurano gli esiti senza che i ricercatori cerchino di influenzare il risultato, ad esempio con un trattamento. Gli studi di coorte ne sono un esempio. Poiché i gruppi non sono assegnati in modo casuale, gli studi osservazionali possono mostrare associazioni ma non possono dimostrare una causa.","synonyme":["Studi osservazionali"],"synonyme_en":["Studi osservazionali"],"siehe":["cohort-study","association","rct"],"seiten":["studien.html"]},{"slug":"bioregulator","begriff":"Bioregolatori","begriff_en":"Bioregolatori","kategorie":"klassen","kurz":"I bioregolatori sono peptidi sintetici molto corti di due a quattro aminoacidi studiati nei sistemi organici.","kurz_en":"I bioregolatori sono peptidi sintetici molto corti di due a quattro aminoacidi studiati nei sistemi organici.","quellen":[{"titel":"Khavinson et al. (2003): Ipotesi della regolazione genica","titel_en":"Khavinson et al. (2003): Ipotesi della regolazione genica","url":"https://pubmed.ncbi.nlm.nih.gov/14666197/"}],"text":"In alcune parti della ricerca sui peptidi, questo termine descrive brevi sequenze investigate per il coinvolgimento nella regolazione genica. Non è una categoria regolatoria che stabilisce l'efficacia. I risultati cellulari individuali non stabiliscono benefici organo specifici né l'estensione della vita umana.","text_en":"In alcune parti della ricerca sui peptidi, questo termine descrive brevi sequenze investigate per il coinvolgimento nella regolazione genica. Non è una categoria regolatoria che stabilisce l'efficacia. I risultati cellulari individuali non stabiliscono benefici organo specifici né l'estensione della vita umana.","synonyme":["Bioregolatori peptidici","Peptidi Khavinson"],"synonyme_en":["Bioregolatori peptidici","Peptidi Khavinson"],"siehe":["oligopeptid","peptid"],"wirkstoffe":["epitalon"],"seiten":["peptid-1x1.html"]},{"slug":"bioverfuegbarkeit","begriff":"Biodisponibilità","begriff_en":"Biodisponibilità","kategorie":"grundlagen","kurz":"La proporzione di una sostanza che raggiunge il flusso sanguigno invariata e può essere misurata lì.","kurz_en":"La proporzione di una sostanza che raggiunge il flusso sanguigno invariata e può essere misurata lì.","quellen":[{"titel":"NCBI Bookshelf: Biodisponibilità dei farmaci","titel_en":"NCBI Bookshelf: Biodisponibilità dei farmaci","url":"https://www.ncbi.nlm.nih.gov/books/NBK557852/"}],"text":"La biodisponibilità indica quale proporzione di una sostanza somministrata raggiunge in ultima analisi la circolazione sistemica invariata, misurata come percentuale. Dipende in parte da quanto la sostanza viene degradata dagli enzimi, come attraverso la proteolisi, durante il suo percorso nel corpo. Gli studi farmacocinetici determinano la biodisponibilità separatamente per diverse vie di somministrazione.","text_en":"La biodisponibilità indica quale proporzione di una sostanza somministrata raggiunge in ultima analisi la circolazione sistemica invariata, misurata come percentuale. Dipende in parte da quanto la sostanza viene degradata dagli enzimi, come attraverso la proteolisi, durante il suo percorso nel corpo. Gli studi farmacocinetici determinano la biodisponibilità separatamente per diverse vie di somministrazione.","siehe":["halbwertszeit","proteolyse"]},{"slug":"blindtest","begriff":"Test cieco","begriff_en":"Test cieco","kategorie":"labor","kurz":"Test cieco: le persone coinvolte non conoscono dettagli rilevanti sul campione.","kurz_en":"Test cieco: le persone coinvolte non conoscono dettagli rilevanti sul campione.","quellen":[{"titel":"Karanicolas et al. (2010): Cieco e sue limitazioni","titel_en":"Karanicolas et al. (2010): Cieco e sue limitazioni","url":"https://pubmed.ncbi.nlm.nih.gov/20858381/"},{"titel":"Peptide Compass: Metodologia e limiti di verifica","titel_en":"Peptide Compass: Metodologia e limiti di verifica","url":"https://peptidkompass.com/it/methodik.html"}],"text":"In un test di laboratorio cieco, le informazioni sull'origine di un campione vengono trattenute prima dell'analisi. Ciò può ridurre il bias di aspettativa ma non può escludere errore o bias. Campionamento, metodi e tracciabilità documentata sono ancora importanti. Peptide Compass non conduce i propri test ciechi.","text_en":"In un test di laboratorio cieco, le informazioni sull'origine di un campione vengono trattenute prima dell'analisi. Ciò può ridurre il bias di aspettativa ma non può escludere errore o bias. Campionamento, metodi e tracciabilità documentata sono ancora importanti. Peptide Compass non conduce i propri test ciechi.","siehe":["drittlabor","coa"],"seiten":["methodik.html"]},{"slug":"bpc-157","begriff":"BPC-157","begriff_en":"BPC-157","kategorie":"wirkstoff","kurz":"Peptide sintetico investigato in modelli preclinici.","kurz_en":"Peptide sintetico investigato in modelli preclinici.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 27847966","titel_en":"PubMed: Pubblicazione di ricerca, PMID 27847966","url":"https://pubmed.ncbi.nlm.nih.gov/27847966/"}],"text":"Lo studio cellulare e animale collegato investiga la formazione di vasi sanguigni e la segnalazione VEGFR2. Tali risultati preclinici non stabiliscono efficacia o uso sicuro in esseri umani.","text_en":"Lo studio cellulare e animale collegato investiga la formazione di vasi sanguigni e la segnalazione VEGFR2. Tali risultati preclinici non stabiliscono efficacia o uso sicuro in esseri umani.","synonyme":["Composto di Protezione Corporea 157","PL 14736"],"synonyme_en":["Composto di Protezione Corporea 157","PL 14736"],"link":"wirkstoffe/bpc-157.html"},{"slug":"cagrilintid","begriff":"Cagrilintide","begriff_en":"Cagrilintide","kategorie":"wirkstoff","kurz":"Analogo di amilina sintetico investigato in ricerca metabolica.","kurz_en":"Analogo di amilina sintetico investigato in ricerca metabolica.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 34288673","titel_en":"PubMed: Pubblicazione di ricerca, PMID 34288673","url":"https://pubmed.ncbi.nlm.nih.gov/34288673/"}],"text":"Il documento di sviluppo citato descrive la struttura e la selezione di un analogo di amilina a lunga durata d'azione. Una medicina in fase di investigazione deve essere distinta da un prodotto chimico di ricerca venduto con lo stesso nome.","text_en":"Il documento di sviluppo citato descrive la struttura e la selezione di un analogo di amilina a lunga durata d'azione. Una medicina in fase di investigazione deve essere distinta da un prodotto chimico di ricerca venduto con lo stesso nome.","synonyme":["AM833","NN9838"],"synonyme_en":["AM833","NN9838"],"link":"wirkstoffe/cagrilintid.html"},{"slug":"charge","begriff":"Lotto","begriff_en":"Lotto","kategorie":"labor","kurz":"Un lotto è una singola produzione con il proprio numero di lotto, quello a cui si riferisce effettivamente un CoA.","kurz_en":"Un lotto è una singola produzione con il proprio numero di lotto, quello a cui si riferisce effettivamente un CoA.","quellen":[{"titel":"ICH Q7: Produzione, lotti e certificati di analisi","titel_en":"ICH Q7: Produzione, lotti e certificati di analisi","url":"https://www.fda.gov/media/71518/download"}],"text":"Il numero di lotto collega un particolare flacone al rapporto corrispondente, il che rende tracciabile un risultato. Un CoA senza un riferimento di lotto chiaro non può essere collegato a un prodotto effettivo e dice corrispondentemente poco.","text_en":"Il numero di lotto collega un particolare flacone al rapporto corrispondente, il che rende tracciabile un risultato. Un CoA senza un riferimento di lotto chiaro non può essere collegato a un prodotto effettivo e dice corrispondentemente poco.","synonyme":["Lotto"],"synonyme_en":["Lotto"],"siehe":["coa","drittlabor"],"seiten":["charge-pruefen.html"]},{"slug":"chromatogramm","begriff":"Cromatogramma","begriff_en":"Cromatogramma","kategorie":"labor","kurz":"Una registrazione grafica della separazione cromatografica, ad esempio in HPLC.","kurz_en":"Una registrazione grafica della separazione cromatografica, ad esempio in HPLC.","quellen":[{"titel":"IUPAC Gold Book: Cromatogramma","titel_en":"IUPAC Gold Book: Cromatogramma","url":"https://goldbook.iupac.org/terms/view/C01071"}],"text":"Un cromatogramma mostra il segnale del rilevatore durante la separazione cromatografica. I picchi possono sovrapporsi. Le percentuali di area dipendono dal metodo e dal rilevatore e non sono automaticamente percentuali di massa. Un cromatogramma da solo non conferma l'identità del peptide.","text_en":"Un cromatogramma mostra il segnale del rilevatore durante la separazione cromatografica. I picchi possono sovrapporsi. Le percentuali di area dipendono dal metodo e dal rilevatore e non sono automaticamente percentuali di massa. Un cromatogramma da solo non conferma l'identità del peptide.","siehe":["hplc","reinheit"],"seiten":["peptid-1x1.html"]},{"slug":"cjc-1295","begriff":"CJC-1295","begriff_en":"CJC-1295","kategorie":"wirkstoff","kurz":"Analogo GHRH sintetico investigato nella ricerca endocrina.","kurz_en":"Analogo GHRH sintetico investigato nella ricerca endocrina.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 16352683","titel_en":"PubMed: Pubblicazione di ricerca, PMID 16352683","url":"https://pubmed.ncbi.nlm.nih.gov/16352683/"}],"text":"Il paper collegato investiga un analogo GHRH a lunga durata d'azione in adulti sani. Il composto studiato deve essere distinto dalle forme modificate diversamente offerte sotto nomi commerciali simili.","text_en":"Il paper collegato investiga un analogo GHRH a lunga durata d'azione in adulti sani. Il composto studiato deve essere distinto dalle forme modificate diversamente offerte sotto nomi commerciali simili.","synonyme":["CJC-1295 con DAC","DAC:GRF"],"synonyme_en":["CJC-1295 con DAC","DAC:GRF"],"link":"wirkstoffe/cjc-1295.html"},{"slug":"coa","begriff":"CoA","begriff_en":"CoA","kategorie":"labor","kurz":"Un CoA è un rapporto collegato a un lotto specifico, che elenca il numero di lotto, il metodo di test e valori come purezza o identità.","kurz_en":"Un CoA è un rapporto collegato a un lotto specifico, che elenca il numero di lotto, il metodo di test e valori come purezza o identità.","quellen":[{"titel":"ICH Q7: Produzione, lotti e certificati di analisi","titel_en":"ICH Q7: Produzione, lotti e certificati di analisi","url":"https://www.fda.gov/media/71518/download"}],"langform":"Certificato di Analisi","langform_en":"Certificato di Analisi","text":"Il valore di un CoA dipende dal numero di lotto, poiché solo questo collega un rapporto a un particolare flacone. Un CoA di un campione generico senza collegamento a un lotto reale dice poco sul prodotto effettivo. Le voci comuni includono purezza, identità e talvolta un valore di endotossina.","text_en":"Il valore di un CoA dipende dal numero di lotto, poiché solo questo collega un rapporto a un particolare flacone. Un CoA di un campione generico senza collegamento a un lotto reale dice poco sul prodotto effettivo. Le voci comuni includono purezza, identità e talvolta un valore di endotossina.","synonyme":["Certificato di analisi","Rapporto di test"],"synonyme_en":["Certificato di analisi","Rapporto di test"],"siehe":["charge","reinheit","identitaet","drittlabor"],"seiten":["charge-pruefen.html","peptid-1x1.html"]},{"slug":"datenbasis","begriff":"Copertura delle evidenze","begriff_en":"Copertura delle evidenze","kategorie":"vergleich","kurz":"La copertura delle evidenze mostra quante delle cinque categorie di punteggio sono documentate per un fornitore.","kurz_en":"La copertura delle evidenze mostra quante delle cinque categorie di punteggio sono documentate per un fornitore.","quellen":[{"titel":"Peptide Compass: La nostra metodologia di confronto","titel_en":"Peptide Compass: La nostra metodologia di confronto","url":"https://peptidkompass.com/it/methodik.html"}],"text":"Poiché i criteri mancanti sono omessi dal calcolo del punteggio e i pesi rimanenti sono ridistribuiti, un singolo criterio documentato può già produrre un valore elevato. I fornitori con diverse coperture delle evidenze sono quindi solo parzialmente confrontabili. Il numero di criteri documentati è mostrato accanto al punteggio.","text_en":"Poiché i criteri mancanti sono omessi dal calcolo del punteggio e i pesi rimanenti sono ridistribuiti, un singolo criterio documentato può già produrre un valore elevato. I fornitori con diverse coperture delle evidenze sono quindi solo parzialmente confrontabili. Il numero di criteri documentati è mostrato accanto al punteggio.","siehe":["dokumentationsscore"],"seiten":["methodik.html"]},{"slug":"dihexa","begriff":"Dihexa","begriff_en":"Dihexa","kategorie":"wirkstoff","kurz":"Analogo dell'angiotensina IV sintetico investigato in modelli preclinici.","kurz_en":"Analogo dell'angiotensina IV sintetico investigato in modelli preclinici.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 38489193","titel_en":"PubMed: Pubblicazione di ricerca, PMID 38489193","url":"https://pubmed.ncbi.nlm.nih.gov/38489193/"},{"titel":"PubMed: Espressione di preoccupazione sull'articolo iniziale","titel_en":"PubMed: Espressione di preoccupazione sull'articolo iniziale","url":"https://pubmed.ncbi.nlm.nih.gov/34551989/"}],"text":"Dihexa è investigato in modelli animali. L'articolo iniziale con PMID 23055539 presenta un'Espressione di Preoccupazione e non viene trattato qui come prova sicura. L'articolo collegato aggiuntivo descrive un modello nel ratto e non stabilisce l'uso umano.","text_en":"Dihexa è investigato in modelli animali. L'articolo iniziale con PMID 23055539 presenta un'Espressione di Preoccupazione e non viene trattato qui come prova sicura. L'articolo collegato aggiuntivo descrive un modello nel ratto e non stabilisce l'uso umano.","synonyme":["PNB-0408","N-Hexanoyl-Tyr-Ile-(6)aminoesanamide"],"synonyme_en":["PNB-0408","N-Hexanoyl-Tyr-Ile-(6)aminoesanamide"],"link":"wirkstoffe/dihexa.html"},{"slug":"dokumentationsscore","begriff":"Punteggio documentazione","begriff_en":"Punteggio documentazione","kategorie":"vergleich","kurz":"Il punteggio documentazione mostra quante affermazioni verificate del fornitore sono effettivamente documentate.","kurz_en":"Il punteggio documentazione mostra quante affermazioni verificate del fornitore sono effettivamente documentate.","quellen":[{"titel":"Peptide Compass: La nostra metodologia di confronto","titel_en":"Peptide Compass: La nostra metodologia di confronto","url":"https://peptidkompass.com/it/methodik.html"}],"text":"La metodologia definisce cinque criteri ponderati. Attualmente, la documentazione di laboratorio, le informazioni legali e la spedizione contribuiscono; prezzo e intervallo rimangono non valutati. I criteri mancanti sono omessi e i pesi rimanenti sono normalizzati. Il punteggio non è un sigillo di qualità o una valutazione della sicurezza del prodotto.","text_en":"La metodologia definisce cinque criteri ponderati. Attualmente, la documentazione di laboratorio, le informazioni legali e la spedizione contribuiscono; prezzo e intervallo rimangono non valutati. I criteri mancanti sono omessi e i pesi rimanenti sono normalizzati. Il punteggio non è un sigillo di qualità o una valutazione della sicurezza del prodotto.","siehe":["datenbasis","coa"],"seiten":["methodik.html"]},{"slug":"doppelblind","begriff":"Studio a doppio cieco","begriff_en":"Studio a doppio cieco","kategorie":"studien","kurz":"Un disegno dello studio in cui né i partecipanti né lo staff sanno chi riceve la sostanza attiva o il placebo. Riduce i bias inconsci.","kurz_en":"Un disegno dello studio in cui né i partecipanti né lo staff sanno chi riceve la sostanza attiva o il placebo. Riduce i bias inconsci.","quellen":[{"titel":"NCI: studio a doppio cieco","titel_en":"NCI: studio a doppio cieco","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/double-blind-study"}],"text":"I partecipanti e i membri dello staff dello studio in cieco non conoscono l'assegnazione ai gruppi. Questo può ridurre i bias di aspettativa e di valutazione. La procedura in cieco è una caratteristica di qualità, ma non esclude altri errori metodologici.","text_en":"I partecipanti e i membri dello staff dello studio in cieco non conoscono l'assegnazione ai gruppi. Questo può ridurre i bias di aspettativa e di valutazione. La procedura in cieco è una caratteristica di qualità, ma non esclude altri errori metodologici.","synonyme":["Doppio cieco"],"synonyme_en":["Doppio cieco"],"siehe":["rct","placebo"],"seiten":["studien.html"]},{"slug":"drittlabor","begriff":"Laboratorio di terze parti","begriff_en":"Laboratorio di terze parti","kategorie":"labor","kurz":"Un laboratorio di terze parti è un laboratorio esterno che testa e documenta un campione indipendentemente dal produttore o dal negozio.","kurz_en":"Un laboratorio di terze parti è un laboratorio esterno che testa e documenta un campione indipendentemente dal produttore o dal negozio.","quellen":[{"titel":"ISO/IEC 17025:2017: Competenza dei laboratori di prova","titel_en":"ISO/IEC 17025:2017: Competenza dei laboratori di prova","url":"https://www.iso.org/standard/66912.html"}],"text":"Se un CoA nomina un laboratorio esterno, vale la pena verificare se il nome è verificabile in assoluto e se possiede accreditamenti come l'ISO 17025. Un test cieco è un modo per verificare un risultato indipendentemente su questo.","text_en":"Se un CoA nomina un laboratorio esterno, vale la pena verificare se il nome è verificabile in assoluto e se possiede accreditamenti come l'ISO 17025. Un test cieco è un modo per verificare un risultato indipendentemente su questo.","synonyme":["Laboratorio esterno"],"synonyme_en":["Laboratorio esterno"],"siehe":["coa","iso-17025","blindtest"],"seiten":["methodik.html","charge-pruefen.html"]},{"slug":"dsip","begriff":"DSIP","begriff_en":"DSIP","kategorie":"wirkstoff","kurz":"Peptide induttore del sonno Delta, originariamente descritto in esperimenti su animali.","kurz_en":"Peptide induttore del sonno Delta, originariamente descritto in esperimenti su animali.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 265572","titel_en":"PubMed: Pubblicazione di ricerca, PMID 265572","url":"https://pubmed.ncbi.nlm.nih.gov/265572/"}],"text":"Il DSIP è stato isolato e investigato sperimentalmente in uno studio iniziale su conigli. Il suo nome riflette l'ipotesi di ricerca in quel momento. Non stabilisce un effetto del sonno affidabile negli esseri umani.","text_en":"Il DSIP è stato isolato e investigato sperimentalmente in uno studio iniziale su conigli. Il suo nome riflette l'ipotesi di ricerca in quel momento. Non stabilisce un effetto del sonno affidabile negli esseri umani.","synonyme":["Peptide induttore del sonno Delta","Peptide del sonno Delta"],"synonyme_en":["Peptide induttore del sonno Delta","Peptide del sonno Delta"],"link":"wirkstoffe/dsip.html"},{"slug":"ema","begriff":"EMA","begriff_en":"EMA","kategorie":"recht","kurz":"L'EMA è l'agenzia dell'UE che coordina e valuta le procedure di autorizzazione all'immissione in commercio centralizzate.","kurz_en":"L'EMA è l'agenzia dell'UE che coordina e valuta le procedure di autorizzazione all'immissione in commercio centralizzate.","quellen":[{"titel":"EMA: Decisioni di valutazione e autorizzazione","titel_en":"EMA: Decisioni di valutazione e autorizzazione","url":"https://www.ema.europa.eu/en/about-us/what-we-do/authorisation-medicines/how-ema-evaluates-medicines-human-use"}],"langform":"Agenzia Europea dei Medicinali","langform_en":"Agenzia Europea dei Medicinali","text":"L'Agenzia Europea dei Medicinali coordina la valutazione scientifica nella procedura di autorizzazione centralizzata dell'UE e pubblica i rapporti di valutazione. La Commissione Europea prende la decisione di autorizzazione. Un rapporto EMA non è un certificato di prova per i prodotti venduti da un fornitore di ricerca.","text_en":"L'Agenzia Europea dei Medicinali coordina la valutazione scientifica nella procedura di autorizzazione centralizzata dell'UE e pubblica i rapporti di valutazione. La Commissione Europea prende la decisione di autorizzazione. Un rapporto EMA non è un certificato di prova per i prodotti venduti da un fornitore di ricerca.","siehe":["zulassung","fda"]},{"slug":"endotoxin","begriff":"Endotossina","begriff_en":"Endotossina","kategorie":"labor","kurz":"Le endotossine sono componenti della parete cellulare batterica, con la quantità in un campione solitamente indicata in unità per milligrammo.","kurz_en":"Le endotossine sono componenti della parete cellulare batterica, con la quantità in un campione solitamente indicata in unità per milligrammo.","quellen":[{"titel":"FDA: Test di pirogeno ed endotossine","titel_en":"FDA: Test di pirogeno ed endotossine","url":"https://www.fda.gov/media/83477/download"}],"text":"Le endotossine batteriche sono componenti dei batteri Gram-negativi. I risultati utilizzano unità di endotossina con una quantità di riferimento dichiarata. I test includono metodi LAL convenzionali e reagenti ricombinanti. I test di endotossine, i test di sterilità e i test di purezza chimica rispondono a domande diverse.","text_en":"Le endotossine batteriche sono componenti dei batteri Gram-negativi. I risultati utilizzano unità di endotossina con una quantità di riferimento dichiarata. I test includono metodi LAL convenzionali e reagenti ricombinanti. I test di endotossine, i test di sterilità e i test di purezza chimica rispondono a domande diverse.","siehe":["sterilitaet","coa"],"seiten":["methodik.html"]},{"slug":"epitalon","begriff":"Epitalon","begriff_en":"Epitalon","kategorie":"wirkstoff","kurz":"Tetrapeptide sintetico investigato in colture cellulari per l'attività della telomerasi.","kurz_en":"Tetrapeptide sintetico investigato in colture cellulari per l'attività della telomerasi.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 12937682","titel_en":"PubMed: Pubblicazione di ricerca, PMID 12937682","url":"https://pubmed.ncbi.nlm.nih.gov/12937682/"}],"text":"Il paper citato investiga l'epithalon in colture cellulari di fibroblasti umani. Le osservazioni della telomerasi in cellule isolate non stabiliscono l'estensione della vita umana.","text_en":"Il paper citato investiga l'epithalon in colture cellulari di fibroblasti umani. Le osservazioni della telomerasi in cellule isolate non stabiliscono l'estensione della vita umana.","synonyme":["Epithalon","Tetrapeptide AEDG"],"synonyme_en":["Epithalon","Tetrapeptide AEDG"],"link":"wirkstoffe/epitalon.html"},{"slug":"fallbericht","begriff":"Rapporto di caso","begriff_en":"Rapporto di caso","kategorie":"studien","kurz":"Una descrizione dettagliata di un singolo caso, spesso insolito. Fornisce un'indicazione iniziale ma nessuna prova statistica.","kurz_en":"Una descrizione dettagliata di un singolo caso, spesso insolito. Fornisce un'indicazione iniziale ma nessuna prova statistica.","quellen":[{"titel":"NCI: caso clinico","titel_en":"NCI: caso clinico","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/case-report"}],"text":"Un rapporto di caso descrive osservazioni in una singola persona o in un piccolo gruppo di casi, spesso una reazione insolita o un evento raro. Può stimolare ulteriori ricerche, ma non ha un gruppo di controllo e nessuna analisi statistica. Un rapporto di caso da solo non dimostra un effetto generale.","text_en":"Un rapporto di caso descrive osservazioni in una singola persona o in un piccolo gruppo di casi, spesso una reazione insolita o un evento raro. Può stimolare ulteriori ricerche, ma non ha un gruppo di controllo e nessuna analisi statistica. Un rapporto di caso da solo non dimostra un effetto generale.","synonyme":["Rapporto di Caso"],"synonyme_en":["Rapporto di Caso"],"siehe":["klinische-studie","peer-review"],"seiten":["studien.html"]},{"slug":"fda","begriff":"FDA","begriff_en":"FDA","kategorie":"recht","kurz":"Agenzia degli Stati Uniti responsabile della regolamentazione dei farmaci, degli alimenti e dei dispositivi medici, tra altri prodotti.","kurz_en":"Agenzia degli Stati Uniti responsabile della regolamentazione dei farmaci, degli alimenti e dei dispositivi medici, tra altri prodotti.","quellen":[{"titel":"FDA: Cosa fa e cosa non approva l'agenzia","titel_en":"FDA: Cosa fa e cosa non approva l'agenzia","url":"https://www.fda.gov/consumers/consumer-updates/10-facts-about-what-fda-does-and-does-not-approve"}],"langform":"Food and Drug Administration","langform_en":"Food and Drug Administration","text":"La Food and Drug Administration regola i farmaci, gli alimenti e i dispositivi medici, tra altri prodotti, negli Stati Uniti. Non tutte le categorie di prodotti regolamentati ricevono l'approvazione pre-market. L'approvazione FDA riguarda un prodotto specifico e non l'autorizzazione UE.","text_en":"La Food and Drug Administration regola i farmaci, gli alimenti e i dispositivi medici, tra altri prodotti, negli Stati Uniti. Non tutte le categorie di prodotti regolamentati ricevono l'approvazione pre-market. L'approvazione FDA riguarda un prodotto specifico e non l'autorizzazione UE.","siehe":["zulassung","ema"]},{"slug":"fragment","begriff":"Frammento","begriff_en":"Frammento","kategorie":"grundlagen","kurz":"Una breve sezione di un peptide o proteina endogena più grande, riprodotta sinteticamente.","kurz_en":"Una breve sezione di un peptide o proteina endogena più grande, riprodotta sinteticamente.","quellen":[{"titel":"Purves et al.: Neurotrasmettitori peptidici","titel_en":"Purves et al.: Neurotrasmettitori peptidici","url":"https://www.ncbi.nlm.nih.gov/books/NBK10873/"}],"text":"Un frammento copre solo una sezione della catena amminoacidica originale di un peptide o proteina, non la sequenza completa. Tali sequenze parziali sono sintetizzate per studiare quale parte di una catena è responsabile di proprietà particolari, come il legame al recettore. Un esempio noto è la timosina alfa-1, un frammento di una proteina precursore più grande.","text_en":"Un frammento copre solo una sezione della catena amminoacidica originale di un peptide o proteina, non la sequenza completa. Tali sequenze parziali sono sintetizzate per studiare quale parte di una catena è responsabile di proprietà particolari, come il legame al recettore. Un esempio noto è la timosina alfa-1, un frammento di una proteina precursore più grande.","siehe":["peptid","analogon","sequenz"]},{"slug":"gegenion","begriff":"Cationi di controione","begriff_en":"Cationi di controione","kategorie":"labor","kurz":"Un catione di controione è il partner salino di un peptide, di solito trifluoroacetato (TFA) o acetato, rimasto dalla produzione.","kurz_en":"Un catione di controione è il partner salino di un peptide, di solito trifluoroacetato (TFA) o acetato, rimasto dalla produzione.","quellen":[{"titel":"Hoofnagle et al. (2016): Analisi dei peptidi e manipolazione in laboratorio","titel_en":"Hoofnagle et al. (2016): Analisi dei peptidi e manipolazione in laboratorio","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"Il controione bilancia la carica elettrica. I controioni possono contribuire al peso del campione senza far parte della sequenza di amminoacidi del peptide.","text_en":"Il controione bilancia la carica elettrica. I controioni possono contribuire al peso del campione senza far parte della sequenza di amminoacidi del peptide.","siehe":["peptidgehalt","reinheit"],"seiten":["methodik.html"]},{"slug":"ghk-cu","begriff":"GHK-Cu","begriff_en":"GHK-Cu","kategorie":"wirkstoff","kurz":"Complesso del tripeptide GHK e rame investigato in vari modelli preclinici.","kurz_en":"Complesso del tripeptide GHK e rame investigato in vari modelli preclinici.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 40672369","titel_en":"PubMed: Pubblicazione di ricerca, PMID 40672369","url":"https://pubmed.ncbi.nlm.nih.gov/40672369/"}],"text":"GHK sta per glicil-istidil-lisina. Lo studio collegato investiga il complesso di rame in un modello sperimentale di colite e saggi cellulari. Non è una prova clinica per la cura della pelle o altri usi.","text_en":"GHK sta per glicil-istidil-lisina. Lo studio collegato investiga il complesso di rame in un modello sperimentale di colite e saggi cellulari. Non è una prova clinica per la cura della pelle o altri usi.","synonyme":["Glicil-L-istidil-L-lisina rame","Tripeptide di rame-1"],"synonyme_en":["Glicil-L-istidil-L-lisina rame","Tripeptide di rame-1"],"link":"wirkstoffe/ghk-cu.html"},{"slug":"ghrh","begriff":"GHRH","begriff_en":"GHRH","kategorie":"klassen","kurz":"Il GHRH è un ormone ipotalamico che attiva la ghiandola pituitaria a rilasciare l'ormone della crescita.","kurz_en":"Il GHRH è un ormone ipotalamico che attiva la ghiandola pituitaria a rilasciare l'ormone della crescita.","quellen":[{"titel":"Teichman et al. (2006): Ricerca su un analogo di GHRH","titel_en":"Teichman et al. (2006): Ricerca su un analogo di GHRH","url":"https://pubmed.ncbi.nlm.nih.gov/16352683/"}],"langform":"Ormone di rilascio dell'ormone della crescita","langform_en":"Ormone di rilascio dell'ormone della crescita","text":"L'ormone di rilascio dell'ormone della crescita è un peptide ipotalamico che viaggia tramite il sistema portale pituitario alla ghiandola pituitaria, dove attiva il rilascio dell'ormone della crescita dalle cellule somatotrope. Fa parte dell'asse dell'ormone della crescita ed è il corrispondente dell'inibitore del corpo, la somatostatina. Diversi analoghi sintetici di GHRH legano lo stesso recettore e sono studiati o utilizzati in questo contesto.","text_en":"L'ormone di rilascio dell'ormone della crescita è un peptide ipotalamico che viaggia tramite il sistema portale pituitario alla ghiandola pituitaria, dove attiva il rilascio dell'ormone della crescita dalle cellule somatotrope. Fa parte dell'asse dell'ormone della crescita ed è il corrispondente dell'inibitore del corpo, la somatostatina. Diversi analoghi sintetici di GHRH legano lo stesso recettore e sono studiati o utilizzati in questo contesto.","synonyme":["Somatoliberina"],"synonyme_en":["Somatoliberina"],"siehe":["ghrp","wachstumshormon","rezeptor"],"wirkstoffe":["cjc-1295","tesamorelin","sermorelin"],"seiten":["peptid-1x1.html"]},{"slug":"ghrp","begriff":"GHRP","begriff_en":"GHRP","kategorie":"klassen","kurz":"Gli GHRP sono peptidi sintetici che attivano il rilascio dell'ormone della crescita attraverso il recettore della grelina.","kurz_en":"Gli GHRP sono peptidi sintetici che attivano il rilascio dell'ormone della crescita attraverso il recettore della grelina.","quellen":[{"titel":"Raun et al. (1998): Coinvolgimento del recettore negli GHRP","titel_en":"Raun et al. (1998): Coinvolgimento del recettore negli GHRP","url":"https://pubmed.ncbi.nlm.nih.gov/9849822/"}],"langform":"Peptide di rilascio dell'ormone della crescita","langform_en":"Peptide di rilascio dell'ormone della crescita","text":"I peptidi di rilascio dell'ormone della crescita sono una classe di peptidi sintetici che legano il recettore della grelina (GHS-R) per attivare il rilascio dell'ormone della crescita dalla ghiandola pituitaria. A differenza degli analoghi di GHRH, utilizzano una via di segnalazione separata e sono spesso combinati con gli analoghi di GHRH nella ricerca. Il recettore della grelina è anche coinvolto nella regolazione della fame e dell'appetito.","text_en":"I peptidi di rilascio dell'ormone della crescita sono una classe di peptidi sintetici che legano il recettore della grelina (GHS-R) per attivare il rilascio dell'ormone della crescita dalla ghiandola pituitaria. A differenza degli analoghi di GHRH, utilizzano una via di segnalazione separata e sono spesso combinati con gli analoghi di GHRH nella ricerca. Il recettore della grelina è anche coinvolto nella regolazione della fame e dell'appetito.","synonyme":["Secretagoghi del GH","Secretagoghi dell'ormone della crescita"],"synonyme_en":["Secretagoghi del GH","Secretagoghi dell'ormone della crescita"],"siehe":["ghrh","wachstumshormon","rezeptor"],"wirkstoffe":["ipamorelin","hexarelin"],"seiten":["peptid-1x1.html"]},{"slug":"gip","begriff":"GIP","begriff_en":"GIP","kategorie":"klassen","kurz":"Il GIP è un ormone intestinale che regola il rilascio di insulina dopo pasti ricchi di carboidrati.","kurz_en":"Il GIP è un ormone intestinale che regola il rilascio di insulina dopo pasti ricchi di carboidrati.","quellen":[{"titel":"NIDDK: Fondamenti della ricerca sulle incretine","titel_en":"NIDDK: Fondamenti della ricerca sulle incretine","url":"https://www.niddk.nih.gov/news/archive/2021/story-discovery-medications-diabetes-obesity-emerged-research-pancreatic-hormone"}],"langform":"Polipeptide insulinotropo dipendente dal glucosio","langform_en":"Polipeptide insulinotropo dipendente dal glucosio","text":"Il polipeptide insulinotropo dipendente dal glucosio è il secondo ormone incretin principale insieme al GLP-1. Le cellule K nell'intestino tenue superiore lo rilasciano dopo aver mangiato e lega il recettore del GIP per regolare il rilascio di insulina. È anche coinvolto nel metabolismo dei grassi. Diversi composti più recenti per il diabete e l'obesità combinano il GIP con l'agonismo del recettore del GLP-1.","text_en":"Il polipeptide insulinotropo dipendente dal glucosio è il secondo ormone incretin principale insieme al GLP-1. Le cellule K nell'intestino tenue superiore lo rilasciano dopo aver mangiato e lega il recettore del GIP per regolare il rilascio di insulina. È anche coinvolto nel metabolismo dei grassi. Diversi composti più recenti per il diabete e l'obesità combinano il GIP con l'agonismo del recettore del GLP-1.","siehe":["glp-1","inkretin","rezeptor"],"wirkstoffe":["tirzepatid","retatrutid"],"seiten":["peptid-1x1.html"]},{"slug":"glp-1","begriff":"GLP-1","begriff_en":"GLP-1","kategorie":"klassen","kurz":"Il GLP-1 è un ormone intestinale rilasciato dopo aver mangiato che regola il rilascio di insulina.","kurz_en":"Il GLP-1 è un ormone intestinale rilasciato dopo aver mangiato che regola il rilascio di insulina.","quellen":[{"titel":"NIDDK: Fondamenti della ricerca sulle incretine","titel_en":"NIDDK: Fondamenti della ricerca sulle incretine","url":"https://www.niddk.nih.gov/news/archive/2021/story-discovery-medications-diabetes-obesity-emerged-research-pancreatic-hormone"}],"langform":"Peptide glucagon-simile 1","langform_en":"Peptide glucagon-simile 1","text":"Il peptide glucagon-simile 1 è un ormone incretin rilasciato dalle cellule L nell'intestino tenue dopo aver mangiato. Si lega al recettore GLP-1, regola il rilascio di insulina, rallenta lo svuotamento gastrico ed è coinvolto nel segnale della sazietà nel cervello. Diversi agonisti del recettore GLP-1 sintetici mirano a questo sistema e alcuni sono approvati come farmaci.","text_en":"Il peptide glucagon-simile 1 è un ormone incretin rilasciato dalle cellule L nell'intestino tenue dopo aver mangiato. Si lega al recettore GLP-1, regola il rilascio di insulina, rallenta lo svuotamento gastrico ed è coinvolto nel segnale della sazietà nel cervello. Diversi agonisti del recettore GLP-1 sintetici mirano a questo sistema e alcuni sono approvati come farmaci.","synonyme":["Peptide glucagon-simile-1"],"synonyme_en":["Peptide glucagon-simile-1"],"siehe":["gip","inkretin","rezeptor","agonist"],"wirkstoffe":["semaglutid","tirzepatid","retatrutid","survodutid"],"seiten":["peptid-1x1.html"]},{"slug":"gmp","begriff":"GMP","begriff_en":"GMP","kategorie":"recht","kurz":"GMP è uno standard di qualità riconosciuto per la produzione di prodotti medicinali e prodotti simili.","kurz_en":"GMP è uno standard di qualità riconosciuto per la produzione di prodotti medicinali e prodotti simili.","quellen":[{"titel":"ICH Q7: Produzione, lotti e certificati di analisi","titel_en":"ICH Q7: Produzione, lotti e certificati di analisi","url":"https://www.fda.gov/media/71518/download"}],"langform":"Buone Pratiche di Fabbricazione","langform_en":"Buone Pratiche di Fabbricazione","text":"Le Buone Pratiche di Fabbricazione coprono i requisiti per impianti, processi, documentazione e tracciabilità nella produzione. La GMP è obbligatoria principalmente per i prodotti medicinali autorizzati. Una dichiarazione GMP di un produttore non sostituisce evidenze indipendenti come un CoA pubblico e si applica solo nella misura in cui è documentata.","text_en":"Le Buone Pratiche di Fabbricazione coprono i requisiti per impianti, processi, documentazione e tracciabilità nella produzione. La GMP è obbligatoria principalmente per i prodotti medicinali autorizzati. Una dichiarazione GMP di un produttore non sostituisce evidenze indipendenti come un CoA pubblico e si applica solo nella misura in cui è documentata.","siehe":["zulassung","coa"],"seiten":["methodik.html"]},{"slug":"halbwertszeit","begriff":"Emivita","begriff_en":"Emivita","kategorie":"grundlagen","kurz":"Il tempo necessario affinché la concentrazione di una sostanza nel corpo si dimezzi.","kurz_en":"Il tempo necessario affinché la concentrazione di una sostanza nel corpo si dimezzi.","quellen":[{"titel":"NCBI Bookshelf: Farmacocinetica","titel_en":"NCBI Bookshelf: Farmacocinetica","url":"https://www.ncbi.nlm.nih.gov/books/NBK557744/"}],"text":"L'emivita descrive quanto tempo ci vuole perché la concentrazione di un peptide nel sangue scenda a metà del suo valore iniziale. Viene misurata negli studi farmacocinetici e varia considerevolmente tra i peptidi individuali, in parte a seconda di quanto velocemente gli enzimi endogeni degradano la catena attraverso la proteolisi. Una emivita più breve significa una degradazione più rapida rispetto a una più lunga.","text_en":"L'emivita descrive quanto tempo ci vuole perché la concentrazione di un peptide nel sangue scenda a metà del suo valore iniziale. Viene misurata negli studi farmacocinetici e varia considerevolmente tra i peptidi individuali, in parte a seconda di quanto velocemente gli enzimi endogeni degradano la catena attraverso la proteolisi. Una emivita più breve significa una degradazione più rapida rispetto a una più lunga.","siehe":["proteolyse","bioverfuegbarkeit"]},{"slug":"hazard-ratio","begriff":"Hazard ratio (rapporto di rischio istantaneo)","begriff_en":"Hazard ratio (rapporto di rischio istantaneo)","kategorie":"studien","kurz":"Misura che confronta la frequenza con cui si verifica un evento in due gruppi nel tempo. Un valore di 1 significa nessuna differenza.","kurz_en":"Misura che confronta la frequenza con cui si verifica un evento in due gruppi nel tempo. Un valore di 1 significa nessuna differenza.","quellen":[{"titel":"NCI: hazard ratio","titel_en":"NCI: hazard ratio","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/hazard-ratio"}],"text":"L'hazard ratio (HR) confronta la frequenza con cui un evento, ad esempio la progressione di una malattia, si verifica in un gruppo rispetto a un altro nel tempo. Un valore di 1 significa nessuna differenza; valori superiori o inferiori a 1 indicano in quale gruppo l'evento è stato più frequente. Non dice nulla sul rischio assoluto e si legge insieme a un intervallo di confidenza.","text_en":"L'hazard ratio (HR) confronta la frequenza con cui un evento, ad esempio la progressione di una malattia, si verifica in un gruppo rispetto a un altro nel tempo. Un valore di 1 significa nessuna differenza; valori superiori o inferiori a 1 indicano in quale gruppo l'evento è stato più frequente. Non dice nulla sul rischio assoluto e si legge insieme a un intervallo di confidenza.","synonyme":["HR"],"synonyme_en":["HR"],"siehe":["confidence-interval","cohort-study","rct"],"seiten":["studien.html"]},{"slug":"hexarelin","begriff":"Hexarelin","begriff_en":"Hexarelin","kategorie":"wirkstoff","kurz":"Peptide sintetico investigato negli studi dell'asse dell'ormone della crescita.","kurz_en":"Peptide sintetico investigato negli studi dell'asse dell'ormone della crescita.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 7910650","titel_en":"PubMed: Pubblicazione di ricerca, PMID 7910650","url":"https://pubmed.ncbi.nlm.nih.gov/7910650/"}],"text":"Il paper originale citato descrive l'hexarelin come un peptide sintetico e investiga il rilascio dell'ormone della crescita nei ratti. Tali risultati di modello non stabiliscono un uso umano sicuro.","text_en":"Il paper originale citato descrive l'hexarelin come un peptide sintetico e investiga il rilascio dell'ormone della crescita nei ratti. Tali risultati di modello non stabiliscono un uso umano sicuro.","link":"wirkstoffe/hexarelin.html"},{"slug":"hplc","begriff":"HPLC","begriff_en":"HPLC","kategorie":"labor","kurz":"HPLC è il metodo analitico standard utilizzato per determinare la purezza di un campione di peptide in percentuale.","kurz_en":"HPLC è il metodo analitico standard utilizzato per determinare la purezza di un campione di peptide in percentuale.","quellen":[{"titel":"FDA: Analisi di miscele complesse e peptidi","titel_en":"FDA: Analisi di miscele complesse e peptidi","url":"https://www.fda.gov/industry/generic-drug-user-fee-amendments/fys-2013-2017-regulatory-science-report-complex-mixtures-and-peptides"}],"langform":"Cromatografia liquida ad alte prestazioni","langform_en":"Cromatografia liquida ad alte prestazioni","text":"Il metodo separa un campione nei suoi componenti e misura ciascuno, producendo un cromatogramma con un picco per componente. L'area del picco principale fornisce il valore di purezza dichiarato. L'HPLC da sola non dice nulla sull'identità, ciò richiede anche la spettrometria di massa.","text_en":"Il metodo separa un campione nei suoi componenti e misura ciascuno, producendo un cromatogramma con un picco per componente. L'area del picco principale fornisce il valore di purezza dichiarato. L'HPLC da sola non dice nulla sull'identità, ciò richiede anche la spettrometria di massa.","synonyme":["Cromatografia liquida ad alte prestazioni"],"synonyme_en":["Cromatografia liquida ad alte prestazioni"],"siehe":["reinheit","chromatogramm","massenspektrometrie"],"seiten":["methodik.html","peptid-1x1.html"]},{"slug":"hwg","begriff":"HWG","begriff_en":"HWG","kategorie":"recht","kurz":"La HWG regola la pubblicità di prodotti medicinali e metodi terapeutici al pubblico in Germania.","kurz_en":"La HWG regola la pubblicità di prodotti medicinali e metodi terapeutici al pubblico in Germania.","quellen":[{"titel":"Legge tedesca sulla pubblicità nel sistema sanitario, testo ufficiale","titel_en":"Legge tedesca sulla pubblicità nel sistema sanitario, testo ufficiale","url":"https://www.gesetze-im-internet.de/heilmwerbg/"}],"langform":"Legge sulla pubblicità dei prodotti terapeutici","langform_en":"Legge sulla pubblicità dei prodotti terapeutici","text":"La Legge tedesca sulla pubblicità dei prodotti terapeutici limita il modo in cui i medicinali e i metodi di trattamento possono essere descritti pubblicamente, incluse le affermazioni su malattie o uso umano. Questo è il motivo per cui Peptide Compass descrive le sostanze solo in termini di risultati di ricerca e non fa dichiarazioni su un effetto nel corpo del lettore.","text_en":"La Legge tedesca sulla pubblicità dei prodotti terapeutici limita il modo in cui i medicinali e i metodi di trattamento possono essere descritti pubblicamente, incluse le affermazioni su malattie o uso umano. Questo è il motivo per cui Peptide Compass descrive le sostanze solo in termini di risultati di ricerca e non fa dichiarazioni su un effetto nel corpo del lettore.","siehe":["arzneimittel"],"seiten":["methodik.html"]},{"slug":"identitaet","begriff":"Identità","begriff_en":"Identità","kategorie":"labor","kurz":"L'identità, confermata dalla spettrometria di massa, verifica che un campione contenga effettivamente il peptide dichiarato.","kurz_en":"L'identità, confermata dalla spettrometria di massa, verifica che un campione contenga effettivamente il peptide dichiarato.","quellen":[{"titel":"FDA: Analisi di miscele complesse e peptidi","titel_en":"FDA: Analisi di miscele complesse e peptidi","url":"https://www.fda.gov/industry/generic-drug-user-fee-amendments/fys-2013-2017-regulatory-science-report-complex-mixtures-and-peptides"}],"text":"Di solito viene mostrata tramite LC-MS, una combinazione di cromatografia liquida e spettrometria di massa che misura il peso molecolare. Purezza e identità sono due figure separate, e un CoA completo elenca entrambi. La purezza da sola non dimostra quale molecola sia effettivamente presente.","text_en":"Di solito viene mostrata tramite LC-MS, una combinazione di cromatografia liquida e spettrometria di massa che misura il peso molecolare. Purezza e identità sono due figure separate, e un CoA completo elenca entrambi. La purezza da sola non dimostra quale molecola sia effettivamente presente.","siehe":["massenspektrometrie","reinheit","coa"],"seiten":["peptid-1x1.html"]},{"slug":"igf-1","begriff":"IGF-1","begriff_en":"IGF-1","kategorie":"klassen","kurz":"L'IGF-1 è un ormone prodotto principalmente nel fegato in risposta all'ormone della crescita.","kurz_en":"L'IGF-1 è un ormone prodotto principalmente nel fegato in risposta all'ormone della crescita.","quellen":[{"titel":"NIDDK: Ormone della crescita e IGF-1","titel_en":"NIDDK: Ormone della crescita e IGF-1","url":"https://www.niddk.nih.gov/health-information/endocrine-diseases/acromegaly"}],"langform":"Fattore di crescita insulino-simile 1","langform_en":"Fattore di crescita insulino-simile 1","text":"Il fattore di crescita insulino-simile 1 è prodotto principalmente nel fegato, innescato dal legame dell'ormone della crescita alle cellule epatiche, e circola nel sangue largamente legato a proteine trasportatrici. Si lega al recettore dell'IGF-1 e media gran parte dell'effetto dell'ormone della crescita sul muscolo, sull'osso e sul tessuto connettivo. Un analogo dell'IGF-1 con un'emivita estesa viene utilizzato in ricerca come strumento autonomo, indipendente dalla regolazione del corpo tramite l'ormone della crescita.","text_en":"Il fattore di crescita insulino-simile 1 è prodotto principalmente nel fegato, innescato dal legame dell'ormone della crescita alle cellule epatiche, e circola nel sangue largamente legato a proteine trasportatrici. Si lega al recettore dell'IGF-1 e media gran parte dell'effetto dell'ormone della crescita sul muscolo, sull'osso e sul tessuto connettivo. Un analogo dell'IGF-1 con un'emivita estesa viene utilizzato in ricerca come strumento autonomo, indipendente dalla regolazione del corpo tramite l'ormone della crescita.","synonyme":["Somatomedin C"],"synonyme_en":["Somatomedin C"],"siehe":["wachstumshormon","ghrh","rezeptor"],"wirkstoffe":["igf-1-lr3"],"seiten":["peptid-1x1.html"]},{"slug":"igf-1-lr3","begriff":"IGF-1 LR3","begriff_en":"IGF-1 LR3","kategorie":"wirkstoff","kurz":"Analogo modificato dell'IGF-1 investigato in modelli preclinici.","kurz_en":"Analogo modificato dell'IGF-1 investigato in modelli preclinici.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 7561636","titel_en":"PubMed: Pubblicazione di ricerca, PMID 7561636","url":"https://pubmed.ncbi.nlm.nih.gov/7561636/"}],"text":"Il paper citato investiga il Long R3 IGF-I nelle cavie e descrive una ridotta affinità per le proteine leganti l'IGF. I risultati per questa forma modificata non sono intercambiabili con i risultati per l'IGF-1 endogeno.","text_en":"Il paper citato investiga il Long R3 IGF-I nelle cavie e descrive una ridotta affinità per le proteine leganti l'IGF. I risultati per questa forma modificata non sono intercambiabili con i risultati per l'IGF-1 endogeno.","synonyme":["Long R3 IGF-1","LR3-IGF-1","IGF-1 Long R3"],"synonyme_en":["Long R3 IGF-1","LR3-IGF-1","IGF-1 Long R3"],"link":"wirkstoffe/igf-1-lr3.html"},{"slug":"in-vitro","begriff":"In vitro","begriff_en":"In vitro","kategorie":"studien","kurz":"Un test al di fuori di un organismo vivente, di solito su colture cellulari. Non dice nulla su un effetto negli esseri umani.","kurz_en":"Un test al di fuori di un organismo vivente, di solito su colture cellulari. Non dice nulla su un effetto negli esseri umani.","quellen":[{"titel":"NCI: in vitro","titel_en":"NCI: in vitro","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/in-vitro"}],"text":"Gli studi in vitro esaminano cellule o molecole isolate in un ambiente controllato come una piastra di Petri. Possono mostrare effetti biochimici precoci, ma il contesto cellulare non sostituisce un organismo intero. Questo tipo di dati conta come ricerca di laboratorio e non si traduce sugli esseri umani.","text_en":"Gli studi in vitro esaminano cellule o molecole isolate in un ambiente controllato come una piastra di Petri. Possono mostrare effetti biochimici precoci, ma il contesto cellulare non sostituisce un organismo intero. Questo tipo di dati conta come ricerca di laboratorio e non si traduce sugli esseri umani.","synonyme":["in vitro"],"synonyme_en":["in vitro"],"siehe":["in-vivo","praeklinisch","tiermodell"],"seiten":["studien.html"]},{"slug":"in-vivo","begriff":"In vivo","begriff_en":"In vivo","kategorie":"studien","kurz":"Un'indagine in un organismo vivente. Il termine da solo non distingue i dati animali da quelli umani.","kurz_en":"Un'indagine in un organismo vivente. Il termine da solo non distingue i dati animali da quelli umani.","quellen":[{"titel":"NCI: in vivo","titel_en":"NCI: in vivo","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/in-vivo"}],"text":"In vivo significa che un'indagine avviene in un organismo vivente. Può essere un animale o un essere umano. I risultati della ricerca devono quindi identificare il modello studiato. I risultati sugli animali non possono essere trasferiti direttamente agli esseri umani.","text_en":"In vivo significa che un'indagine avviene in un organismo vivente. Può essere un animale o un essere umano. I risultati della ricerca devono quindi identificare il modello studiato. I risultati sugli animali non possono essere trasferiti direttamente agli esseri umani.","synonyme":["in vivo"],"synonyme_en":["in vivo"],"siehe":["in-vitro","tiermodell","praeklinisch"],"seiten":["studien.html"]},{"slug":"inkretin","begriff":"Incretina","begriff_en":"Incretina","kategorie":"klassen","kurz":"Le incretine sono ormoni intestinali rilasciati dopo il pasto che sono coinvolti nella regolazione del rilascio di insulina.","kurz_en":"Le incretine sono ormoni intestinali rilasciati dopo il pasto che sono coinvolti nella regolazione del rilascio di insulina.","quellen":[{"titel":"NIDDK: Fondamenti della ricerca sulle incretine","titel_en":"NIDDK: Fondamenti della ricerca sulle incretine","url":"https://www.niddk.nih.gov/news/archive/2021/story-discovery-medications-diabetes-obesity-emerged-research-pancreatic-hormone"}],"text":"Le incretine sono una classe di ormoni intestinali che include GLP-1 e GIP. Vengono rilasciate da cellule intestinali specializzate dopo il pasto e legano i propri recettori sulle cellule beta pancreatiche. Attraverso questo meccanismo, il rilascio di insulina dopo l'assunzione orale di glucosio è maggiore rispetto a quello dopo una dose endovenosa della stessa quantità, un effetto noto come effetto incretinico. Diversi farmaci approvati e in fase di studio mimano questa via.","text_en":"Le incretine sono una classe di ormoni intestinali che include GLP-1 e GIP. Vengono rilasciate da cellule intestinali specializzate dopo il pasto e legano i propri recettori sulle cellule beta pancreatiche. Attraverso questo meccanismo, il rilascio di insulina dopo l'assunzione orale di glucosio è maggiore rispetto a quello dopo una dose endovenosa della stessa quantità, un effetto noto come effetto incretinico. Diversi farmaci approvati e in fase di studio mimano questa via.","synonyme":["Ormoni incretinici"],"synonyme_en":["Ormoni incretinici"],"siehe":["glp-1","gip","peptidhormon","rezeptor"],"wirkstoffe":["semaglutid","tirzepatid","retatrutid","survodutid"],"seiten":["peptid-1x1.html"]},{"slug":"ipamorelin","begriff":"Ipamorelina","begriff_en":"Ipamorelina","kategorie":"wirkstoff","kurz":"Pentapeptide sintetico investigato negli studi sul rilascio dell'ormone della crescita.","kurz_en":"Pentapeptide sintetico investigato negli studi sul rilascio dell'ormone della crescita.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 9849822","titel_en":"PubMed: Pubblicazione di ricerca, PMID 9849822","url":"https://pubmed.ncbi.nlm.nih.gov/9849822/"}],"text":"Il documento di sviluppo descrive un pentapeptide e investiga il coinvolgimento dei recettori e il rilascio dell'ormone in modelli cellulari e animali. Questi risultati non possono essere generalmente trasferiti agli esseri umani.","text_en":"Il documento di sviluppo descrive un pentapeptide e investiga il coinvolgimento dei recettori e il rilascio dell'ormone in modelli cellulari e animali. Questi risultati non possono essere generalmente trasferiti agli esseri umani.","synonyme":["NNC 26-0161"],"synonyme_en":["NNC 26-0161"],"link":"wirkstoffe/ipamorelin.html"},{"slug":"iso-17025","begriff":"ISO 17025","begriff_en":"ISO 17025","kategorie":"labor","kurz":"ISO 17025 è la norma internazionale per la competenza tecnica dei laboratori di test e calibrazione.","kurz_en":"ISO 17025 è la norma internazionale per la competenza tecnica dei laboratori di test e calibrazione.","quellen":[{"titel":"ISO/IEC 17025:2017: Competenza dei laboratori di prova","titel_en":"ISO/IEC 17025:2017: Competenza dei laboratori di prova","url":"https://www.iso.org/standard/66912.html"}],"langform":"ISO/IEC 17025","langform_en":"ISO/IEC 17025","text":"L'accreditamento secondo questa norma significa che le procedure, l'attrezzatura e il personale di un laboratorio sono stati valutati in modo indipendente. È un marcatore di qualità per il laboratorio stesso, non una garanzia per un risultato CoA specifico.","text_en":"L'accreditamento secondo questa norma significa che le procedure, l'attrezzatura e il personale di un laboratorio sono stati valutati in modo indipendente. È un marcatore di qualità per il laboratorio stesso, non una garanzia per un risultato CoA specifico.","siehe":["drittlabor","coa"],"seiten":["methodik.html"]},{"slug":"internationale-einheit","begriff":"UI","begriff_en":"UI","kategorie":"handhabung","kurz":"L'Unità Internazionale misura la potenza biologica di una sostanza rispetto a uno standard di riferimento, non il suo peso.","kurz_en":"L'Unità Internazionale misura la potenza biologica di una sostanza rispetto a uno standard di riferimento, non il suo peso.","quellen":[{"titel":"OMS: Standard di riferimento biologico","titel_en":"OMS: Standard di riferimento biologico","url":"https://www.who.int/activities/providing-international-biological-reference-standards"}],"langform":"Unità Internazionale","langform_en":"Unità Internazionale","text":"Per sostanze come l'ormone della crescita, il peso da solo non descrive in modo significativo la quantità, poiché diversi lotti possono variare in purezza allo stesso peso. L'Unità Internazionale stabilisce invece la quantità in relazione a una preparazione di riferimento OMS definita. Un milligrammo di un ormone non equivale quindi automaticamente allo stesso numero di unità di un milligrammo di una preparazione diversa.","text_en":"Per sostanze come l'ormone della crescita, il peso da solo non descrive in modo significativo la quantità, poiché diversi lotti possono variare in purezza allo stesso peso. L'Unità Internazionale stabilisce invece la quantità in relazione a una preparazione di riferimento OMS definita. Un milligrammo di un ormone non equivale quindi automaticamente allo stesso numero di unità di un milligrammo di una preparazione diversa.","synonyme":["UI"],"synonyme_en":["UI"],"siehe":["milligramm-mikrogramm","wachstumshormon"]},{"slug":"kisspeptin","begriff":"Kisspeptina-10","begriff_en":"Kisspeptina-10","kategorie":"wirkstoff","kurz":"Famiglia di peptidi investigata nella ricerca endocrina; questo catalogo si concentra sulla kisspeptina-10.","kurz_en":"Famiglia di peptidi investigata nella ricerca endocrina; questo catalogo si concentra sulla kisspeptina-10.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 21632807","titel_en":"PubMed: Pubblicazione di ricerca, PMID 21632807","url":"https://pubmed.ncbi.nlm.nih.gov/21632807/"}],"text":"Lo studio citato investiga la kisspeptina-10 negli uomini. Altre isoforme come la kisspeptina-54 devono essere considerate separatamente. Il termine ombrello kisspeptina non specifica completamente la forma studiata.","text_en":"Lo studio citato investiga la kisspeptina-10 negli uomini. Altre isoforme come la kisspeptina-54 devono essere considerate separatamente. Il termine ombrello kisspeptina non specifica completamente la forma studiata.","synonyme":["Metastina (45-54)","KP-10"],"synonyme_en":["Metastina (45-54)","KP-10"],"link":"wirkstoffe/kisspeptin.html"},{"slug":"klinische-studie","begriff":"Studio clinico","begriff_en":"Studio clinico","kategorie":"studien","kurz":"Uno studio su partecipanti umani, solitamente strutturato in fasi I a III. Il tipo di studio più informativo per gli esseri umani.","kurz_en":"Uno studio su partecipanti umani, solitamente strutturato in fasi I a III. Il tipo di studio più informativo per gli esseri umani.","quellen":[{"titel":"NCI: studio clinico","titel_en":"NCI: studio clinico","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/clinical-trial"}],"text":"Uno studio clinico investiga una questione medica che coinvolge persone. Gli studi differiscono per dimensione, gruppi di confronto, cieco e risultati misurati. Queste caratteristiche aiutano a determinare quanto affidabile sia un risultato. La registrazione o la pubblicazione di uno studio da sola non stabilisce l'approvazione o la qualità di un prodotto commerciale.","text_en":"Uno studio clinico investiga una questione medica che coinvolge persone. Gli studi differiscono per dimensione, gruppi di confronto, cieco e risultati misurati. Queste caratteristiche aiutano a determinare quanto affidabile sia un risultato. La registrazione o la pubblicazione di uno studio da sola non stabilisce l'approvazione o la qualità di un prodotto commerciale.","synonyme":["Studio clinico"],"synonyme_en":["Studio clinico"],"siehe":["studienphasen","rct","placebo","Doppio cieco"],"seiten":["studien.html"]},{"slug":"cohort-study","begriff":"Studio di coorte","begriff_en":"Studio di coorte","kategorie":"studien","kurz":"Studio osservazionale che segue nel tempo gruppi diversi per una caratteristica e confronta un esito.","kurz_en":"Studio osservazionale che segue nel tempo gruppi diversi per una caratteristica e confronta un esito.","quellen":[{"titel":"NCI: studio di coorte","titel_en":"NCI: studio di coorte","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/cohort-study"}],"text":"In uno studio di coorte, gruppi di persone che differiscono per una caratteristica (ad esempio fumare o non fumare) vengono seguiti per un periodo e si confronta un determinato esito. I ricercatori non intervengono. Tali studi mostrano associazioni, non causa ed effetto, perché i gruppi possono differire anche in altri aspetti.","text_en":"In uno studio di coorte, gruppi di persone che differiscono per una caratteristica (ad esempio fumare o non fumare) vengono seguiti per un periodo e si confronta un determinato esito. I ricercatori non intervengono. Tali studi mostrano associazioni, non causa ed effetto, perché i gruppi possono differire anche in altri aspetti.","synonyme":["Studi di coorte"],"synonyme_en":["Studi di coorte"],"siehe":["observational-study","association","confounder"],"seiten":["studien.html"]},{"slug":"confidence-interval","begriff":"Intervallo di confidenza","begriff_en":"Intervallo di confidenza","kategorie":"studien","kurz":"Intervallo di valori costruito per includere il valore reale con una probabilità stabilita, di solito il 95%.","kurz_en":"Intervallo di valori costruito per includere il valore reale con una probabilità stabilita, di solito il 95%.","quellen":[{"titel":"NLM MeSH: Confidence Intervals","titel_en":"NLM MeSH: Confidence Intervals","url":"https://www.ncbi.nlm.nih.gov/mesh/68016001"}],"text":"Un intervallo di confidenza (IC) è un intervallo di valori costruito in modo da includere il valore reale di una grandezza, come un tasso o un hazard ratio, con una probabilità stabilita, di solito il 95%. Un intervallo stretto suggerisce una stima più precisa. Se l'intervallo di un hazard ratio include 1, una differenza tra i gruppi non è statisticamente stabilita.","text_en":"Un intervallo di confidenza (IC) è un intervallo di valori costruito in modo da includere il valore reale di una grandezza, come un tasso o un hazard ratio, con una probabilità stabilita, di solito il 95%. Un intervallo stretto suggerisce una stima più precisa. Se l'intervallo di un hazard ratio include 1, una differenza tra i gruppi non è statisticamente stabilita.","synonyme":["IC","Intervallo fiduciario"],"synonyme_en":["IC","Intervallo fiduciario"],"siehe":["hazard-ratio","metaanalyse"],"seiten":["studien.html"]},{"slug":"konzentration","begriff":"Concentrazione","begriff_en":"Concentrazione","kategorie":"handhabung","kurz":"La concentrazione indica quanta di una sostanza è disciolta in un dato volume di liquido, di solito in mg per ml.","kurz_en":"La concentrazione indica quanta di una sostanza è disciolta in un dato volume di liquido, di solito in mg per ml.","quellen":[{"titel":"IUPAC Gold Book: Concentrazione in massa","titel_en":"IUPAC Gold Book: Concentrazione in massa","url":"https://goldbook.iupac.org/terms/view/M03713"}],"text":"La concentrazione in massa riporta la massa di una sostanza specificata rispetto al volume finale della soluzione, ad esempio in mg/ml. Il peso della polvere e la massa effettiva del peptide possono differire. Questo valore descrive la composizione, non un'applicazione.","text_en":"La concentrazione in massa riporta la massa di una sostanza specificata rispetto al volume finale della soluzione, ad esempio in mg/ml. Il peso della polvere e la massa effettiva del peptide possono differire. Questo valore descrive la composizione, non un'applicazione.","siehe":["rekonstitution","milligramm-mikrogramm","aliquot"]},{"slug":"kpv","begriff":"KPV","begriff_en":"KPV","kategorie":"wirkstoff","kurz":"Tripeptide derivato da melanocortina investigato in modelli di infiammazione preclinici","kurz_en":"Tripeptide derivato da melanocortina investigato in modelli di infiammazione preclinici","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 18092346","titel_en":"PubMed: Pubblicazione di ricerca, PMID 18092346","url":"https://pubmed.ncbi.nlm.nih.gov/18092346/"}],"text":"KPV sta per lisina-prolina-valina, un frammento corto nel contesto della melanocortina. Il paper citato l'investiga in modelli murini di malattia infiammatoria intestinale. Questa non è prova clinica di uso.","text_en":"KPV sta per lisina-prolina-valina, un frammento corto nel contesto della melanocortina. Il paper citato l'investiga in modelli murini di malattia infiammatoria intestinale. Questa non è prova clinica di uso.","synonyme":["Lys-Pro-Val","alpha-MSH(11-13)"],"synonyme_en":["Lys-Pro-Val","alpha-MSH(11-13)"],"link":"wirkstoffe/kpv.html"},{"slug":"kupferpeptid","begriff":"Peptidi di rame","begriff_en":"Peptidi di rame","kategorie":"klassen","kurz":"I peptidi di rame sono complessi di un piccolo peptide e uno ione di rame, il più noto è GHK-Cu.","kurz_en":"I peptidi di rame sono complessi di un piccolo peptide e uno ione di rame, il più noto è GHK-Cu.","quellen":[{"titel":"GHK come peptide legante il rame in cristallografia","titel_en":"GHK come peptide legante il rame in cristallografia","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7709198/"}],"text":"I peptidi di rame sono composti in cui un piccolo peptide coordina uno ione di rame. L'esempio più noto è GHK, un peptide a tre amminoacidi trovato nel plasma sanguigno, nella saliva e nell'urina umana, dove si trova naturalmente legato al rame. Nella sua forma complesso di rame, GHK-Cu è studiato principalmente nella ricerca sulla pelle, con dati preclinici aggiuntivi sul tessuto connettivo e sulla guarigione delle ferite.","text_en":"I peptidi di rame sono composti in cui un piccolo peptide coordina uno ione di rame. L'esempio più noto è GHK, un peptide a tre amminoacidi trovato nel plasma sanguigno, nella saliva e nell'urina umana, dove si trova naturalmente legato al rame. Nella sua forma complesso di rame, GHK-Cu è studiato principalmente nella ricerca sulla pelle, con dati preclinici aggiuntivi sul tessuto connettivo e sulla guarigione delle ferite.","synonyme":["Complessi GHK-Cu"],"synonyme_en":["Complessi GHK-Cu"],"siehe":["aminosaeure","peptid"],"wirkstoffe":["ghk-cu"],"seiten":["peptid-1x1.html"]},{"slug":"lagerung","begriff":"Conservazione","begriff_en":"Conservazione","kategorie":"handhabung","kurz":"La conservazione descrive come un peptide viene mantenuto prima dell'uso, di solito fresco, asciutto e al buio a seconda del suo stato.","kurz_en":"La conservazione descrive come un peptide viene mantenuto prima dell'uso, di solito fresco, asciutto e al buio a seconda del suo stato.","quellen":[{"titel":"Hoofnagle et al. (2016): Analisi dei peptidi e manipolazione in laboratorio","titel_en":"Hoofnagle et al. (2016): Analisi dei peptidi e manipolazione in laboratorio","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"La stabilità dipende dalla sequenza, dalla formulazione e dalle condizioni, tra altri fattori. La specifica del materiale e i dati di stabilità accertati sono decisivi.","text_en":"La stabilità dipende dalla sequenza, dalla formulazione e dalle condizioni, tra altri fattori. La specifica del materiale e i dati di stabilità accertati sono decisivi.","siehe":["lyophilisat","lichtschutz","rekonstitution"]},{"slug":"lichtschutz","begriff":"Protezione dalla luce","begriff_en":"Protezione dalla luce","kategorie":"handhabung","kurz":"La protezione dalla luce copre misure che schermano un campione dall'esposizione alla luce, come fiale color ambra o conservazione al buio.","kurz_en":"La protezione dalla luce copre misure che schermano un campione dall'esposizione alla luce, come fiale color ambra o conservazione al buio.","quellen":[{"titel":"ICH Q1B: test di fotostabilità","titel_en":"ICH Q1B: test di fotostabilità","url":"https://www.ema.europa.eu/en/scientific-guidelines/ich-q1b-photostability-testing-new-active-substances-medicinal-products"}],"text":"I test di fotostabilità investigano se la luce modifica una sostanza o una formulazione. L'imballaggio adatto può limitare l'esposizione. Le condizioni richieste sono specifiche del prodotto; la sola protezione dalla luce non stabilisce una durata di conservazione particolare.","text_en":"I test di fotostabilità investigano se la luce modifica una sostanza o una formulazione. L'imballaggio adatto può limitare l'esposizione. Le condizioni richieste sono specifiche del prodotto; la sola protezione dalla luce non stabilisce una durata di conservazione particolare.","siehe":["lagerung","lyophilisat"]},{"slug":"ll-37","begriff":"LL-37","begriff_en":"LL-37","kategorie":"wirkstoff","kurz":"Peptide antimicrobico endogeno anche investigato nella ricerca sulle ferite cliniche.","kurz_en":"Peptide antimicrobico endogeno anche investigato nella ricerca sulle ferite cliniche.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 25041740","titel_en":"PubMed: Pubblicazione di ricerca, PMID 25041740","url":"https://pubmed.ncbi.nlm.nih.gov/25041740/"}],"text":"Lo studio randomizzato collegato investiga LL-37 nelle ulcere venose delle gambe difficili da guarire. I suoi risultati riguardano la preparazione e il disegno dello studio specifico, non ogni prodotto etichettato LL-37.","text_en":"Lo studio randomizzato collegato investiga LL-37 nelle ulcere venose delle gambe difficili da guarire. I suoi risultati riguardano la preparazione e il disegno dello studio specifico, non ogni prodotto etichettato LL-37.","synonyme":["Catelicidina","hCAP18(134-170)","Catelicidina umana"],"synonyme_en":["Catelicidina","hCAP18(134-170)","Catelicidina umana"],"link":"wirkstoffe/ll-37.html"},{"slug":"lyophilisat","begriff":"Liofilizzato","begriff_en":"Liofilizzato","kategorie":"handhabung","kurz":"Materiale ottenuto per liofilizzazione, come una polvere in un viale di laboratorio.","kurz_en":"Materiale ottenuto per liofilizzazione, come una polvere in un viale di laboratorio.","quellen":[{"titel":"FDA: Liofilizzazione","titel_en":"FDA: Liofilizzazione","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/inspection-guides/lyophilization-parenteral-793"}],"text":"La liofilizzazione rimuove l'acqua da un campione congelato sotto vuoto. Lascia una polvere secca o una torta porosa. La stabilità e la durata di conservazione dipendono dalla sostanza, dalla formulazione e dall'imballaggio; la forma fisica da sola non le garantisce.","text_en":"La liofilizzazione rimuove l'acqua da un campione congelato sotto vuoto. Lascia una polvere secca o una torta porosa. La stabilità e la durata di conservazione dipendono dalla sostanza, dalla formulazione e dall'imballaggio; la forma fisica da sola non le garantisce.","siehe":["rekonstitution","lagerung","lichtschutz","charge"]},{"slug":"massenspektrometrie","begriff":"Spettrometria di massa","begriff_en":"Spettrometria di massa","kategorie":"labor","kurz":"La spettrometria di massa determina il peso molecolare di un campione e quindi conferma quale molecola è effettivamente presente.","kurz_en":"La spettrometria di massa determina il peso molecolare di un campione e quindi conferma quale molecola è effettivamente presente.","quellen":[{"titel":"FDA: Analisi di miscele complesse e peptidi","titel_en":"FDA: Analisi di miscele complesse e peptidi","url":"https://www.fda.gov/industry/generic-drug-user-fee-amendments/fys-2013-2017-regulatory-science-report-complex-mixtures-and-peptides"}],"text":"Combinata con la cromatografia liquida (LC-MS), verifica l'identità di un peptide indipendentemente dal suo valore di purezza. Un valore di purezza elevato senza questa verifica non dice nulla sulla presenza della molecola corretta.","text_en":"Combinata con la cromatografia liquida (LC-MS), verifica l'identità di un peptide indipendentemente dal suo valore di purezza. Un valore di purezza elevato senza questa verifica non dice nulla sulla presenza della molecola corretta.","synonyme":["MS"],"synonyme_en":["MS"],"siehe":["identitaet","hplc","coa"],"seiten":["peptid-1x1.html"]},{"slug":"melanocortin","begriff":"Melanocortine","begriff_en":"Melanocortine","kategorie":"klassen","kurz":"Le melanocortine sono ormoni peptidici derivati da POMC che legano cinque tipi di recettori che regolano la pelle, l'appetito e la risposta sessuale.","kurz_en":"Le melanocortine sono ormoni peptidici derivati da POMC che legano cinque tipi di recettori che regolano la pelle, l'appetito e la risposta sessuale.","quellen":[{"titel":"NCBI Endotext: Recettori delle melanocortine","titel_en":"NCBI Endotext: Recettori delle melanocortine","url":"https://www.ncbi.nlm.nih.gov/books/NBK279118/"}],"text":"Le melanocortine sono una famiglia di ormoni peptidici derivati dalla proteina precursore proopiomelanocortina (POMC), inclusi alpha-MSH e ACTH. Le legano cinque recettori delle melanocortine distinti (MC1R a MC5R) che regolano la pigmentazione della pelle, l'appetito, il bilancio energetico, i processi infiammatori e la risposta sessuale, tra altre funzioni. Gli agonisti dei recettori delle melanocortine sintetici mirano a recettori individuali all'interno di questo sistema.","text_en":"Le melanocortine sono una famiglia di ormoni peptidici derivati dalla proteina precursore proopiomelanocortina (POMC), inclusi alpha-MSH e ACTH. Le legano cinque recettori delle melanocortine distinti (MC1R a MC5R) che regolano la pigmentazione della pelle, l'appetito, il bilancio energetico, i processi infiammatori e la risposta sessuale, tra altre funzioni. Gli agonisti dei recettori delle melanocortine sintetici mirano a recettori individuali all'interno di questo sistema.","synonyme":["Sistema delle melanocortine"],"synonyme_en":["Sistema delle melanocortine"],"siehe":["rezeptor","agonist","peptidhormon"],"wirkstoffe":["melanotan-2","pt-141"],"seiten":["peptid-1x1.html"]},{"slug":"melanotan-2","begriff":"Melanotan II","begriff_en":"Melanotan II","kategorie":"wirkstoff","kurz":"Analogo di melanocortina sintetico investigato in studi clinici iniziali.","kurz_en":"Analogo di melanocortina sintetico investigato in studi clinici iniziali.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 8637402","titel_en":"PubMed: Pubblicazione di ricerca, PMID 8637402","url":"https://pubmed.ncbi.nlm.nih.gov/8637402/"}],"text":"Il paper di fase I citato investiga il melanotan II in uno studio pilota su piccola scala. Non stabilisce una valutazione affidabile del rapporto beneficio-rischio per l'uso generale.","text_en":"Il paper di fase I citato investiga il melanotan II in uno studio pilota su piccola scala. Non stabilisce una valutazione affidabile del rapporto beneficio-rischio per l'uso generale.","synonyme":["MT-2","MT2"],"synonyme_en":["MT-2","MT2"],"link":"wirkstoffe/melanotan-2.html"},{"slug":"metaanalyse","begriff":"Meta-analisi","begriff_en":"Meta-analisi","kategorie":"studien","kurz":"Una sintesi statistica di più studi che affrontano una domanda comune.","kurz_en":"Una sintesi statistica di più studi che affrontano una domanda comune.","quellen":[{"titel":"NCI: metanalisi","titel_en":"NCI: metanalisi","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/meta-analysis"}],"text":"Una meta-analisi combina statisticamente risultati comparabili da più studi. Può fornire stime più precise. La sua forza dipende dalla qualità, comparabilità e completezza delle evidenze incluse.","text_en":"Una meta-analisi combina statisticamente risultati comparabili da più studi. Può fornire stime più precise. La sua forza dipende dalla qualità, comparabilità e completezza delle evidenze incluse.","siehe":["klinische-studie","peer-review"],"seiten":["studien.html"]},{"slug":"milligramm-mikrogramm","begriff":"Milligrammo / Microgrammo","begriff_en":"Milligrammo / Microgrammo","kategorie":"handhabung","kurz":"Un milligrammo equivale a 1000 microgrammi, l'unità di massa standard per piccole quantità di peptidi sulle etichette e sui CoA.","kurz_en":"Un milligrammo equivale a 1000 microgrammi, l'unità di massa standard per piccole quantità di peptidi sulle etichette e sui CoA.","quellen":[{"titel":"BIPM: prefissi SI","titel_en":"BIPM: prefissi SI","url":"https://www.bipm.org/en/committees/cg/cgpm/11-1960/resolution-12"}],"text":"Milligrammi (mg) e microgrammi (µg) sono entrambi sotto-unità del grammo e differiscono per un fattore di 1000. Le etichette dei vasi e i CoA indicano solitamente la quantità di peptide in milligrammi, mentre le cifre dei componenti individuali appaiono talvolta in microgrammi. Il calcolatore su questa pagina converte tra grammi, milligrammi e microgrammi su base puramente matematica.","text_en":"Milligrammi (mg) e microgrammi (µg) sono entrambi sotto-unità del grammo e differiscono per un fattore di 1000. Le etichette dei vasi e i CoA indicano solitamente la quantità di peptide in milligrammi, mentre le cifre dei componenti individuali appaiono talvolta in microgrammi. Il calcolatore su questa pagina converte tra grammi, milligrammi e microgrammi su base puramente matematica.","siehe":["konzentration","internationale-einheit"],"seiten":["rechner.html"]},{"slug":"mitochondriales-peptid","begriff":"Peptidi mitocondriali","begriff_en":"Peptidi mitocondriali","kategorie":"klassen","kurz":"I peptidi mitocondriali mirano alla produzione di energia cellulare o derivano dal DNA mitocondriale.","kurz_en":"I peptidi mitocondriali mirano alla produzione di energia cellulare o derivano dal DNA mitocondriale.","quellen":[{"titel":"Lee et al. (2015): MOTS-c, ricerca preclinica","titel_en":"Lee et al. (2015): MOTS-c, ricerca preclinica","url":"https://doi.org/10.1016/j.cmet.2015.02.009"},{"titel":"Cho et al. (2007): Bersagli mitocondriali in un modello nel ratto","titel_en":"Cho et al. (2007): Bersagli mitocondriali in un modello nel ratto","url":"https://pubmed.ncbi.nlm.nih.gov/17429296/"}],"text":"I peptidi mitocondriali non sono una singola classe di sostanze nel senso classico. Il termine raggruppa peptidi che si legano alla membrana mitocondriale interna o sono codificati dal DNA mitocondriale piuttosto che dal DNA nucleare. Il secondo gruppo include un peptide corto derivato dal gene 12S rRNA mitocondriale, studiato nella ricerca metabolica. Un altro esempio si lega alla cardiolina nella membrana interna ed è utilizzato nella ricerca sul invecchiamento cellulare e sul metabolismo energetico.","text_en":"I peptidi mitocondriali non sono una singola classe di sostanze nel senso classico. Il termine raggruppa peptidi che si legano alla membrana mitocondriale interna o sono codificati dal DNA mitocondriale piuttosto che dal DNA nucleare. Il secondo gruppo include un peptide corto derivato dal gene 12S rRNA mitocondriale, studiato nella ricerca metabolica. Un altro esempio si lega alla cardiolina nella membrana interna ed è utilizzato nella ricerca sul invecchiamento cellulare e sul metabolismo energetico.","synonyme":["Peptidi mitocondriali"],"synonyme_en":["Peptidi mitocondriali"],"siehe":["praeklinisch","in-vitro"],"wirkstoffe":["mots-c","ss-31"],"seiten":["studien.html"]},{"slug":"mots-c","begriff":"MOTS-c","begriff_en":"MOTS-c","kategorie":"wirkstoff","kurz":"Peptide derivato dal DNA mitocondriale investigato in modelli metabolici preclinici.","kurz_en":"Peptide derivato dal DNA mitocondriale investigato in modelli metabolici preclinici.","quellen":[{"titel":"Lee et al. (2015): MOTS-c, ricerca preclinica","titel_en":"Lee et al. (2015): MOTS-c, ricerca preclinica","url":"https://doi.org/10.1016/j.cmet.2015.02.009"}],"text":"Il paper di scoperta descrive una sequenza corta codificata nel DNA mitocondriale e l'investiga in modelli cellulari e animali. Il suo ruolo nella ricerca mitocondriale non stabilisce un beneficio di un prodotto commercializzato.","text_en":"Il paper di scoperta descrive una sequenza corta codificata nel DNA mitocondriale e l'investiga in modelli cellulari e animali. Il suo ruolo nella ricerca mitocondriale non stabilisce un beneficio di un prodotto commercializzato.","synonyme":["Peptide Derivato Mitocondriale MOTS-c","Frame di Lettura Aperto Mitocondriale dell'rRNA 12S Tipo-c"],"synonyme_en":["Peptide Derivato Mitocondriale MOTS-c","Frame di Lettura Aperto Mitocondriale dell'rRNA 12S Tipo-c"],"link":"wirkstoffe/mots-c.html"},{"slug":"neuropeptid","begriff":"Neuropeptide","begriff_en":"Neuropeptide","kategorie":"grundlagen","kurz":"Un peptide che agisce come molecola di segnalazione tra le cellule nel sistema nervoso.","kurz_en":"Un peptide che agisce come molecola di segnalazione tra le cellule nel sistema nervoso.","quellen":[{"titel":"Purves et al.: Neurotrasmettitori peptidici","titel_en":"Purves et al.: Neurotrasmettitori peptidici","url":"https://www.ncbi.nlm.nih.gov/books/NBK10873/"}],"text":"I neuropeptidi sono peptidi rilasciati dalle cellule nervose che agiscono come molecole di segnalazione all'interno del sistema nervoso. Sono diversi dai neurotrasmettitori classici per la loro struttura molecolare più grande e si legano anche a recettori specifici sulle cellule bersaglio. Nella ricerca, i neuropeptidi sono utilizzati tra le altre cose per mappare le vie di segnalazione nel sistema nervoso centrale.","text_en":"I neuropeptidi sono peptidi rilasciati dalle cellule nervose che agiscono come molecole di segnalazione all'interno del sistema nervoso. Sono diversi dai neurotrasmettitori classici per la loro struttura molecolare più grande e si legano anche a recettori specifici sulle cellule bersaglio. Nella ricerca, i neuropeptidi sono utilizzati tra le altre cose per mappare le vie di segnalazione nel sistema nervoso centrale.","siehe":["peptid","peptidhormon","rezeptor"]},{"slug":"nootropikum","begriff":"Nootropici","begriff_en":"Nootropici","kategorie":"klassen","kurz":"I nootropici sono una classe di sostanze ampia studiata in relazione alla memoria, all'apprendimento o all'elaborazione dello stress.","kurz_en":"I nootropici sono una classe di sostanze ampia studiata in relazione alla memoria, all'apprendimento o all'elaborazione dello stress.","quellen":[{"titel":"Giurgea (1972): Origine del concetto di nootropico","titel_en":"Giurgea (1972): Origine del concetto di nootropico","url":"https://pubmed.ncbi.nlm.nih.gov/4541214/"}],"text":"Coined by Giurgea nel 1972, il termine descrive sostanze investigate in relazione alle funzioni cognitive. L'etichetta da sola non stabilisce né beneficio né sicurezza. Diverse sostanze e disegni di studio richiedono una valutazione separata.","text_en":"Coined by Giurgea nel 1972, il termine descrive sostanze investigate in relazione alle funzioni cognitive. L'etichetta da sola non stabilisce né beneficio né sicurezza. Diverse sostanze e disegni di studio richiedono una valutazione separata.","synonyme":["Smart drug"],"synonyme_en":["Smart drug"],"siehe":["neuropeptid","rezeptor"],"wirkstoffe":["semax","selank","dihexa"],"seiten":["peptid-1x1.html"]},{"slug":"oligopeptid","begriff":"Oligopeptide","begriff_en":"Oligopeptide","kategorie":"grundlagen","kurz":"Una catena corta di amminoacidi, classificata per lunghezza come di-, tri- o oligopeptide.","kurz_en":"Una catena corta di amminoacidi, classificata per lunghezza come di-, tri- o oligopeptide.","quellen":[{"titel":"Alberts et al.: Struttura proteica","titel_en":"Alberts et al.: Struttura proteica","url":"https://www.ncbi.nlm.nih.gov/books/NBK26830/"}],"langform":"Di-, tri- e oligopeptide","langform_en":"Di-, tri- e oligopeptide","text":"Gli oligopeptidi contengono un piccolo numero di amminoacidi. Due formano un dipeptide e tre un tripeptide. Il confine con i polipeptidi più lunghi è una convenzione di denominazione, non un cambiamento distinto nel tipo molecolare.","text_en":"Gli oligopeptidi contengono un piccolo numero di amminoacidi. Due formano un dipeptide e tre un tripeptide. Il confine con i polipeptidi più lunghi è una convenzione di denominazione, non un cambiamento distinto nel tipo molecolare.","synonyme":["Dipeptide","Tripeptide"],"synonyme_en":["Dipeptide","Tripeptide"],"siehe":["peptid","aminosaeure","protein"],"seiten":["peptid-1x1.html"]},{"slug":"oxytocin","begriff":"Ossitocina","begriff_en":"Ossitocina","kategorie":"wirkstoff","kurz":"L'ormone peptidico endogeno è anche investigato negli studi sul comportamento sociale.","kurz_en":"L'ormone peptidico endogeno è anche investigato negli studi sul comportamento sociale.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 15931222","titel_en":"PubMed: Pubblicazione di ricerca, PMID 15931222","url":"https://pubmed.ncbi.nlm.nih.gov/15931222/"}],"text":"Lo studio comportamentale collegato investiga le decisioni in un gioco di fiducia sperimentale. Tali risultati non stabiliscono né relazioni sociali generalmente migliorate né la sicurezza dei prodotti commercializzati liberamente.","text_en":"Lo studio comportamentale collegato investiga le decisioni in un gioco di fiducia sperimentale. Tali risultati non stabiliscono né relazioni sociali generalmente migliorate né la sicurezza dei prodotti commercializzati liberamente.","synonyme":["OXT","Pitocin"],"synonyme_en":["OXT","Pitocin"],"link":"wirkstoffe/oxytocin.html"},{"slug":"partnercode","begriff":"Codice partner","begriff_en":"Codice partner","kategorie":"vergleich","kurz":"Un codice associato a un programma di affiliazione, soggetto ai termini del fornitore.","kurz_en":"Un codice associato a un programma di affiliazione, soggetto ai termini del fornitore.","quellen":[{"titel":"Peptide Compass: La nostra dichiarazione affiliata","titel_en":"Peptide Compass: La nostra dichiarazione affiliata","url":"https://peptidkompass.com/it/affiliate-hinweis.html"}],"text":"Un codice partner è associato a un programma di affiliazione. Il fatto che generi uno sconto o una commissione dipende dai termini applicabili. Le partnership e i codici documentati attualmente sono elencati nella nostra dichiarazione di affiliazione; non modificano il punteggio della documentazione.","text_en":"Un codice partner è associato a un programma di affiliazione. Il fatto che generi uno sconto o una commissione dipende dai termini applicabili. Le partnership e i codici documentati attualmente sono elencati nella nostra dichiarazione di affiliazione; non modificano il punteggio della documentazione.","siehe":["affiliate-link"],"seiten":["affiliate-hinweis.html","deals.html"]},{"slug":"peer-review","begriff":"Revisione paritaria","begriff_en":"Revisione paritaria","kategorie":"studien","kurz":"Revisione da parte di esperti di uno studio di manoscritto prima della pubblicazione.","kurz_en":"Revisione da parte di esperti di uno studio di manoscritto prima della pubblicazione.","quellen":[{"titel":"NIH: Linee guida per la revisione paritaria scientifica","titel_en":"NIH: Linee guida per la revisione paritaria scientifica","url":"https://oir.nih.gov/system/files/media/file/2026-01/guidelines-conduct_research.pdf"}],"text":"Nella revisione paritaria, esperti indipendenti controllano la metodologia, l'analisi dei dati e le conclusioni di un manoscritto prima della pubblicazione. Possono richiedere correzioni o respingere il lavoro. Una pubblicazione sottoposta a revisione paritaria è considerata più affidabile di un testo non revisionato, sebbene non sia una garanzia contro l'errore.","text_en":"Nella revisione paritaria, esperti indipendenti controllano la metodologia, l'analisi dei dati e le conclusioni di un manoscritto prima della pubblicazione. Possono richiedere correzioni o respingere il lavoro. Una pubblicazione sottoposta a revisione paritaria è considerata più affidabile di un testo non revisionato, sebbene non sia una garanzia contro l'errore.","siehe":["preprint","pubmed"],"seiten":["studien.html"]},{"slug":"pentadeca-arginate","begriff":"Pentadeca Arginate (PDA)","begriff_en":"Pentadeca Arginate","kategorie":"wirkstoff","kurz":"Designazione commerciale per una forma commercializzata come sale di arginina di BPC-157.","kurz_en":"Designazione commerciale per una forma commercializzata come sale di arginina di BPC-157.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 27847966","titel_en":"PubMed: Pubblicazione di ricerca, PMID 27847966","url":"https://pubmed.ncbi.nlm.nih.gov/27847966/"}],"text":"Lo studio originale citato investiga il BPC-157. Non stabilisce proprietà speciali di una forma salina venduta come pentadeca arginate. Non è stata stabilita qui una fonte affidabile e dedicata che dimostri una solubilità o stabilità superiore di questa forma commercializzata.","text_en":"Lo studio originale citato investiga il BPC-157. Non stabilisce proprietà speciali di una forma salina venduta come pentadeca arginate. Non è stata stabilita qui una fonte affidabile e dedicata che dimostri una solubilità o stabilità superiore di questa forma commercializzata.","synonyme":["PDA","Sale di arginina di BPC-157"],"synonyme_en":["PDA","Sale di arginina di BPC-157"],"link":"wirkstoffe/pentadeca-arginate.html"},{"slug":"peptid","begriff":"Peptide","begriff_en":"Peptidi","kategorie":"grundlagen","kurz":"Una catena corta di amminoacidi collegati da legami peptidici.","kurz_en":"Una catena corta di amminoacidi collegati da legami peptidici.","quellen":[{"titel":"NCI: peptide","titel_en":"NCI: peptide","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/peptide"}],"text":"Due amminoacidi collegati formano un dipeptide; tre formano un tripeptide. Le catene più lunghe sono anche chiamate polipeptidi. Un limite fisso di 50 amminoacidi non distingue i peptidi dalle proteine in ogni campo.","text_en":"Due amminoacidi collegati formano un dipeptide; tre formano un tripeptide. Le catene più lunghe sono anche chiamate polipeptidi. Un limite fisso di 50 amminoacidi non distingue i peptidi dalle proteine in ogni campo.","synonyme":["Peptidi"],"synonyme_en":["Peptidi"],"siehe":["aminosaeure","peptidbindung","oligopeptid","protein"],"seiten":["peptid-1x1.html"]},{"slug":"peptidbindung","begriff":"Legame peptidico","begriff_en":"Legame peptidico","kategorie":"grundlagen","kurz":"Il legame chimico che unisce due amminoacidi in una catena.","kurz_en":"Il legame chimico che unisce due amminoacidi in una catena.","quellen":[{"titel":"Alberts et al.: Struttura proteica","titel_en":"Alberts et al.: Struttura proteica","url":"https://www.ncbi.nlm.nih.gov/books/NBK26830/"}],"text":"Un legame peptidico si forma quando il gruppo carbossilico di un amminoacido reagisce con il gruppo amminico del successivo, rilasciando una molecola d'acqua nel processo. Questo legame si ripete lungo tutta la catena e forma lo scheletro dei peptidi e delle proteine. L'ordine degli amminoacidi uniti in questo modo stabilisce la sequenza.","text_en":"Un legame peptidico si forma quando il gruppo carbossilico di un amminoacido reagisce con il gruppo amminico del successivo, rilasciando una molecola d'acqua nel processo. Questo legame si ripete lungo tutta la catena e forma lo scheletro dei peptidi e delle proteine. L'ordine degli amminoacidi uniti in questo modo stabilisce la sequenza.","siehe":["aminosaeure","peptid","sequenz"]},{"slug":"peptidgehalt","begriff":"Contenuto netto di peptide","begriff_en":"Contenuto netto di peptide","kategorie":"labor","kurz":"Il contenuto netto di peptide indica quale quota della massa di una polvere è effettivamente il peptide stesso.","kurz_en":"Il contenuto netto di peptide indica quale quota della massa di una polvere è effettivamente il peptide stesso.","quellen":[{"titel":"Hoofnagle et al. (2016): Analisi dei peptidi e manipolazione in laboratorio","titel_en":"Hoofnagle et al. (2016): Analisi dei peptidi e manipolazione in laboratorio","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"Il contenuto di peptide è la frazione di peptide effettiva di un campione. Acqua e altri costituenti possono far differire la massa della polvere dalla massa del peptide.","text_en":"Il contenuto di peptide è la frazione di peptide effettiva di un campione. Acqua e altri costituenti possono far differire la massa della polvere dalla massa del peptide.","siehe":["reinheit","gegenion","coa"],"seiten":["methodik.html"]},{"slug":"peptidhormon","begriff":"Ormone peptidico","begriff_en":"Ormone peptidico","kategorie":"grundlagen","kurz":"Un ormone che il corpo produce che è chimicamente una catena di aminoacidi.","kurz_en":"Un ormone che il corpo produce che è chimicamente una catena di aminoacidi.","quellen":[{"titel":"Purves et al.: Neurotrasmettitori peptidici","titel_en":"Purves et al.: Neurotrasmettitori peptidici","url":"https://www.ncbi.nlm.nih.gov/books/NBK10873/"}],"text":"Un ormone peptidico è una molecola di segnalazione costruita da una catena di aminoacidi, a differenza degli ormoni steroidei, che sono basati sul colesterolo. Gli ormoni peptidici sono prodotti in ghiandole o cellule specializzate e si legano ai recettori sulle cellule bersaglio. L'insulina è un esempio ben noto di un ormone peptidico endogeno.","text_en":"Un ormone peptidico è una molecola di segnalazione costruita da una catena di aminoacidi, a differenza degli ormoni steroidei, che sono basati sul colesterolo. Gli ormoni peptidici sono prodotti in ghiandole o cellule specializzate e si legano ai recettori sulle cellule bersaglio. L'insulina è un esempio ben noto di un ormone peptidico endogeno.","siehe":["peptid","rezeptor","neuropeptid"]},{"slug":"placebo","begriff":"Placebo","begriff_en":"Placebo","kategorie":"studien","kurz":"Una preparazione fittizia senza principio attivo, utilizzata per confrontarla con una sostanza reale in uno studio. Separa gli effetti reali da quelli attesi.","kurz_en":"Una preparazione fittizia senza principio attivo, utilizzata per confrontarla con una sostanza reale in uno studio. Separa gli effetti reali da quelli attesi.","quellen":[{"titel":"NCI: placebo","titel_en":"NCI: placebo","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/placebo"}],"text":"Un placebo assomiglia alla preparazione testata ma non contiene principio attivo. In un disegno dello studio funge da gruppo di confronto, mostrando quanta parte della risposta deriva dall'aspettativa del partecipante piuttosto che dalla sostanza stessa. Il controllo placebo è una caratteristica fondamentale degli studi clinici informativi, spesso combinato con l'offuscamento.","text_en":"Un placebo assomiglia alla preparazione testata ma non contiene principio attivo. In un disegno dello studio funge da gruppo di confronto, mostrando quanta parte della risposta deriva dall'aspettativa del partecipante piuttosto che dalla sostanza stessa. Il controllo placebo è una caratteristica fondamentale degli studi clinici informativi, spesso combinato con l'offuscamento.","synonyme":["Preparazione inattiva"],"synonyme_en":["Preparazione inattiva"],"siehe":["rct","Doppio cieco"],"seiten":["studien.html"]},{"slug":"praeklinisch","begriff":"Preclinico","begriff_en":"Preclinico","kategorie":"studien","kurz":"La fase di ricerca prima di qualsiasi uso umano: coltura cellulare e modello animale. Gli studi clinici seguono solo dopo questa fase.","kurz_en":"La fase di ricerca prima di qualsiasi uso umano: coltura cellulare e modello animale. Gli studi clinici seguono solo dopo questa fase.","quellen":[{"titel":"NCI: studio preclinico","titel_en":"NCI: studio preclinico","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/preclinical-study"}],"text":"La ricerca preclinica copre esperimenti in vitro e in vivo che verificano effetti e sicurezza precoci prima che una sostanza venga mai testata su esseri umani. Fornisce la base dati per un possibile futuro studio clinico. Un risultato preclinico da solo non supporta un'affermazione su esseri umani.","text_en":"La ricerca preclinica copre esperimenti in vitro e in vivo che verificano effetti e sicurezza precoci prima che una sostanza venga mai testata su esseri umani. Fornisce la base dati per un possibile futuro studio clinico. Un risultato preclinico da solo non supporta un'affermazione su esseri umani.","synonyme":["Ricerca preclinica"],"synonyme_en":["Ricerca preclinica"],"siehe":["in-vitro","in-vivo","tiermodell","klinische-studie"],"seiten":["studien.html"]},{"slug":"preis-pro-mg","begriff":"Prezzo per milligrammo","begriff_en":"Prezzo per milligrammo","kategorie":"vergleich","kurz":"Il prezzo per milligrammo rende direttamente confrontabili le offerte con diverse dimensioni di confezione.","kurz_en":"Il prezzo per milligrammo rende direttamente confrontabili le offerte con diverse dimensioni di confezione.","quellen":[{"titel":"Peptide Compass: La nostra metodologia di confronto","titel_en":"Peptide Compass: La nostra metodologia di confronto","url":"https://peptidkompass.com/it/methodik.html"}],"text":"La cifra è il prezzo di listino diviso per il contenuto in milligrammi di un prodotto, confrontato per la stessa sostanza attiva e valuta. Termini di spedizione, disponibilità e sconti sono inclusi solo se esplicitamente documentati. Una cifra inferiore non dice nulla sulla purezza o sulla documentazione.","text_en":"La cifra è il prezzo di listino diviso per il contenuto in milligrammi di un prodotto, confrontato per la stessa sostanza attiva e valuta. Termini di spedizione, disponibilità e sconti sono inclusi solo se esplicitamente documentati. Una cifra inferiore non dice nulla sulla purezza o sulla documentazione.","siehe":["dokumentationsscore"],"seiten":["vergleich.html","rechner.html"]},{"slug":"preprint","begriff":"Preprint","begriff_en":"Preprint","kategorie":"studien","kurz":"Manoscritto di studio pubblicato prima della revisione paritaria. I risultati sono considerati preliminari, non ancora verificati indipendentemente.","kurz_en":"Manoscritto di studio pubblicato prima della revisione paritaria. I risultati sono considerati preliminari, non ancora verificati indipendentemente.","quellen":[{"titel":"NLM: Limitazioni di PubMed e preprint","titel_en":"NLM: Limitazioni di PubMed e preprint","url":"https://pubmed.ncbi.nlm.nih.gov/disclaimer/"}],"text":"Un preprint viene pubblicato su una piattaforma aperta prima che una rivista l'abbia esaminato. Questo accelera lo scambio di risultati ma significa che la metodologia e le conclusioni non sono ancora state verificate indipendentemente. Il contenuto di un preprint dovrebbe essere giudicato con maggiore cautela rispetto a una pubblicazione sottoposta a revisione paritaria.","text_en":"Un preprint viene pubblicato su una piattaforma aperta prima che una rivista l'abbia esaminato. Questo accelera lo scambio di risultati ma significa che la metodologia e le conclusioni non sono ancora state verificate indipendentemente. Il contenuto di un preprint dovrebbe essere giudicato con maggiore cautela rispetto a una pubblicazione sottoposta a revisione paritaria.","siehe":["peer-review","pubmed"],"seiten":["studien.html"]},{"slug":"protein","begriff":"Proteina","begriff_en":"Proteina","kategorie":"grundlagen","kurz":"Una molecola fatta di catene di aminoacidi con diversi ruoli biologici.","kurz_en":"Una molecola fatta di catene di aminoacidi con diversi ruoli biologici.","quellen":[{"titel":"NCI: proteina","titel_en":"NCI: proteina","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/protein"}],"text":"Le proteine consistono in una o più catene di aminoacidi. La loro sequenza e struttura spaziale determinano le loro proprietà. Una lunghezza di catena fissa da sola non definisce la distinzione dai peptidi.","text_en":"Le proteine consistono in una o più catene di aminoacidi. La loro sequenza e struttura spaziale determinano le loro proprietà. Una lunghezza di catena fissa da sola non definisce la distinzione dai peptidi.","synonyme":["Proteina"],"synonyme_en":["Proteina"],"siehe":["peptid","aminosaeure","oligopeptid"],"seiten":["peptid-1x1.html"]},{"slug":"proteolyse","begriff":"Proteolisi","begriff_en":"Proteolisi","kategorie":"grundlagen","kurz":"La rottura enzimatica di una catena di aminoacidi in frammenti più piccoli.","kurz_en":"La rottura enzimatica di una catena di aminoacidi in frammenti più piccoli.","quellen":[{"titel":"Alberts et al.: Sintesi e degradazione delle proteine","titel_en":"Alberts et al.: Sintesi e degradazione delle proteine","url":"https://www.ncbi.nlm.nih.gov/books/NBK26829/"}],"text":"La proteolisi è il processo mediante il quale enzimi chiamati proteasi scindono i legami peptidici in una catena di aminoacidi, spezzandola in frammenti più piccoli. Questa rottura avviene continuamente nel corpo e influenza quanto a lungo un peptide rimane integro, in altre parole la sua emivita. Gli studi riportano spesso la stabilità proteolitica come misura della durata di un peptide.","text_en":"La proteolisi è il processo mediante il quale enzimi chiamati proteasi scindono i legami peptidici in una catena di aminoacidi, spezzandola in frammenti più piccoli. Questa rottura avviene continuamente nel corpo e influenza quanto a lungo un peptide rimane integro, in altre parole la sua emivita. Gli studi riportano spesso la stabilità proteolitica come misura della durata di un peptide.","siehe":["halbwertszeit","peptidbindung","bioverfuegbarkeit"]},{"slug":"pt-141","begriff":"PT-141 (bremelanotide)","begriff_en":"PT-141 (bremelanotide)","kategorie":"wirkstoff","kurz":"Bremelanotide, un agonista del recettore della melanocortina sintetico investigato in studi clinici.","kurz_en":"Bremelanotide, un agonista del recettore della melanocortina sintetico investigato in studi clinici.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 31599840","titel_en":"PubMed: Pubblicazione di ricerca, PMID 31599840","url":"https://pubmed.ncbi.nlm.nih.gov/31599840/"}],"text":"PT-141 è un altro nome per bremelanotide. La pubblicazione collegata descrive due studi randomizzati di fase III in una popolazione di pazienti definita. Un prodotto di ricerca venduto da un negozio non è equivalente alla preparazione dello studio.","text_en":"PT-141 è un altro nome per bremelanotide. La pubblicazione collegata descrive due studi randomizzati di fase III in una popolazione di pazienti definita. Un prodotto di ricerca venduto da un negozio non è equivalente alla preparazione dello studio.","synonyme":["Bremelanotide","Vyleesi"],"synonyme_en":["Bremelanotide","Vyleesi"],"link":"wirkstoffe/pt-141.html"},{"slug":"pubmed","begriff":"PubMed","begriff_en":"PubMed","kategorie":"studien","kurz":"Un database gratuito gestito dalla National Library of Medicine degli Stati Uniti per la letteratura biomedica.","kurz_en":"Un database gratuito gestito dalla National Library of Medicine degli Stati Uniti per la letteratura biomedica.","quellen":[{"titel":"NLM: Limitazioni di PubMed e preprint","titel_en":"NLM: Limitazioni di PubMed e preprint","url":"https://pubmed.ncbi.nlm.nih.gov/disclaimer/"}],"text":"PubMed indice milioni di articoli dalla medicina e dalle scienze della vita e di solito mostra un abstract gratuito direttamente. Il testo completo si trova spesso dietro il paywall della rispettiva rivista. Un elenco PubMed conferma che un articolo è indicizzato, ma non dice nulla sulla qualità di quello studio individuale.","text_en":"PubMed indice milioni di articoli dalla medicina e dalle scienze della vita e di solito mostra un abstract gratuito direttamente. Il testo completo si trova spesso dietro il paywall della rispettiva rivista. Un elenco PubMed conferma che un articolo è indicizzato, ma non dice nulla sulla qualità di quello studio individuale.","siehe":["peer-review","preprint"],"seiten":["studien.html"]},{"slug":"rct","begriff":"RCT","begriff_en":"RCT","kategorie":"studien","kurz":"Un disegno dello studio con assegnazione casuale a un trattamento e a un gruppo di controllo. Considerato lo standard aureo per dimostrare un effetto.","kurz_en":"Un disegno dello studio con assegnazione casuale a un trattamento e a un gruppo di controllo. Considerato lo standard aureo per dimostrare un effetto.","quellen":[{"titel":"NCI: Studi clinici randomizzati","titel_en":"NCI: Studi clinici randomizzati","url":"https://www.cancer.gov/publications/patient-education/crs.pdf"}],"langform":"Studio clinico randomizzato controllato","langform_en":"Studio clinico randomizzato controllato","text":"In uno studio clinico randomizzato controllato, i partecipanti vengono assegnati a caso a un trattamento o a un gruppo di controllo, spesso ciechi anche. Ciò riduce il bias da aspettativa o selezione. Gli RCT sono considerati lo standard aureo metodologico nella ricerca clinica, specialmente combinati con controllo placebo.","text_en":"In uno studio clinico randomizzato controllato, i partecipanti vengono assegnati a caso a un trattamento o a un gruppo di controllo, spesso ciechi anche. Ciò riduce il bias da aspettativa o selezione. Gli RCT sono considerati lo standard aureo metodologico nella ricerca clinica, specialmente combinati con controllo placebo.","siehe":["placebo","Doppio cieco","klinische-studie"],"seiten":["studien.html"]},{"slug":"reinheit","begriff":"Purezza","begriff_en":"Purezza","kategorie":"labor","kurz":"La purezza indica quanta dell'area del picco del cromatogramma di un campione appartiene alla molecola principale, di solito come percentuale da HPLC.","kurz_en":"La purezza indica quanta dell'area del picco del cromatogramma di un campione appartiene alla molecola principale, di solito come percentuale da HPLC.","quellen":[{"titel":"Hoofnagle et al. (2016): Analisi dei peptidi e manipolazione in laboratorio","titel_en":"Hoofnagle et al. (2016): Analisi dei peptidi e manipolazione in laboratorio","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"La purezza descrive la proporzione della sostanza bersaglio all'interno di un metodo dichiarato. Una percentuale di area HPLC non stabilisce completamente la composizione.","text_en":"La purezza descrive la proporzione della sostanza bersaglio all'interno di un metodo dichiarato. Una percentuale di area HPLC non stabilisce completamente la composizione.","siehe":["hplc","identitaet","peptidgehalt"],"seiten":["peptid-1x1.html"]},{"slug":"rekonstitution","begriff":"Ricostituzione","begriff_en":"Ricostituzione","kategorie":"handhabung","kurz":"La ricostituzione è sciogliere un peptide liofilizzato in un liquido per preparare una soluzione per l'uso in laboratorio.","kurz_en":"La ricostituzione è sciogliere un peptide liofilizzato in un liquido per preparare una soluzione per l'uso in laboratorio.","quellen":[{"titel":"FDA: Liofilizzazione","titel_en":"FDA: Liofilizzazione","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/inspection-guides/lyophilization-parenteral-793"}],"text":"Il termine significa ripristinare una forma liquida da una preparazione secca. Il liquido adatto dipende dalla sostanza e dalla procedura analitica. Il termine non implica un metodo generale di preparazione o somministrazione.","text_en":"Il termine significa ripristinare una forma liquida da una preparazione secca. Il liquido adatto dipende dalla sostanza e dalla procedura analitica. Il termine non implica un metodo generale di preparazione o somministrazione.","siehe":["lyophilisat","bakteriostatisches-wasser","steriles-wasser","konzentration"],"seiten":["rechner.html"]},{"slug":"retatrutid","begriff":"Retatrutide","begriff_en":"Retatrutide","kategorie":"wirkstoff","kurz":"Agonista a triplo recettore peptidico investigato in studi clinici.","kurz_en":"Agonista a triplo recettore peptidico investigato in studi clinici.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 37366315","titel_en":"PubMed: Pubblicazione di ricerca, PMID 37366315","url":"https://pubmed.ncbi.nlm.nih.gov/37366315/"}],"text":"Lo studio di fase II collegato investiga un agonista ai recettori GIP, GLP-1 e glucagone. I risultati di quello studio non stabiliscono l'equivalenza di un prodotto commerciale venduto con lo stesso nome.","text_en":"Lo studio di fase II collegato investiga un agonista ai recettori GIP, GLP-1 e glucagone. I risultati di quello studio non stabiliscono l'equivalenza di un prodotto commerciale venduto con lo stesso nome.","synonyme":["LY3437943"],"synonyme_en":["LY3437943"],"link":"wirkstoffe/retatrutid.html"},{"slug":"rezeptor","begriff":"Recettore","begriff_en":"Recettore","kategorie":"grundlagen","kurz":"Una proteina su o all'interno di una cellula a cui un peptide si lega specificamente.","kurz_en":"Una proteina su o all'interno di una cellula a cui un peptide si lega specificamente.","quellen":[{"titel":"NCI: recettore","titel_en":"NCI: recettore","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/receptor"}],"text":"Un recettore è una proteina che riconosce e lega specificamente una molecola corrispondente, come un peptide, simile a una serratura e una chiave. Questo legame innesca una catena di segnalazione all'interno della cellula. Nella ricerca, la forza con cui un peptide si lega a un dato recettore è chiamata affinità e viene spesso studiata in laboratorio utilizzando colture cellulari.","text_en":"Un recettore è una proteina che riconosce e lega specificamente una molecola corrispondente, come un peptide, simile a una serratura e una chiave. Questo legame innesca una catena di segnalazione all'interno della cellula. Nella ricerca, la forza con cui un peptide si lega a un dato recettore è chiamata affinità e viene spesso studiata in laboratorio utilizzando colture cellulari.","siehe":["agonist","peptidhormon","neuropeptid"]},{"slug":"rezeptpflicht","begriff":"Requisito di prescrizione","begriff_en":"Requisito di prescrizione","kategorie":"recht","kurz":"Un requisito di prescrizione significa che un medicinale può essere dispensato solo su prescrizione medica.","kurz_en":"Un requisito di prescrizione significa che un medicinale può essere dispensato solo su prescrizione medica.","quellen":[{"titel":"Legge sui medicinali tedesca, sezione 48: requisiti di prescrizione","titel_en":"Legge sui medicinali tedesca, sezione 48: requisiti di prescrizione","url":"https://www.gesetze-im-internet.de/amg_1976/__48.html"}],"text":"In Germania, la sezione 48 della Legge sui medicinali e il regolamento sui medicinali su prescrizione sono particolarmente rilevanti. Requisiti di prescrizione, status di medicinale e autorizzazione sono questioni separate. La vendita come prodotto chimico di ricerca non stabilisce un'esenzione generale.","text_en":"In Germania, la sezione 48 della Legge sui medicinali e il regolamento sui medicinali su prescrizione sono particolarmente rilevanti. Requisiti di prescrizione, status di medicinale e autorizzazione sono questioni separate. La vendita come prodotto chimico di ricerca non stabilisce un'esenzione generale.","siehe":["arzneimittel","zulassung"],"seiten":["peptid-1x1.html"]},{"slug":"ruo","begriff":"RUO","begriff_en":"RUO","kategorie":"recht","kurz":"Research Use Only descrive uno scopo di ricerca. L'abbreviazione da sola non stabilisce lo status legale di un prodotto.","kurz_en":"Research Use Only descrive uno scopo di ricerca. L'abbreviazione da sola non stabilisce lo status legale di un prodotto.","quellen":[{"titel":"Legge sui medicinali tedesca, sezione 2: Definizione di medicinali","titel_en":"Legge sui medicinali tedesca, sezione 2: Definizione di medicinali","url":"https://www.gesetze-im-internet.de/amg_1976/__2.html"},{"titel":"FDA (24 agosto 2026): etichettatura RUO e uso previsto, USA","titel_en":"FDA (24 agosto 2026): etichettatura RUO e uso previsto, USA","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/warning-letters/txp-innovations-llc-dba-tex-peptides-735067-08242026"}],"langform":"Research Use Only (solo per uso di ricerca)","langform_en":"Research Use Only (solo per uso di ricerca)","text":"L'etichetta descrive lo scopo previsto dichiarato dal fornitore. Non è né un'autorizzazione né una prova di purezza o sicurezza. Se un prodotto è legalmente qualificato come medicinale dipende dai criteri statutari e dalla sua presentazione effettiva, non solo da questa abbreviazione.","text_en":"L'etichetta descrive lo scopo previsto dichiarato dal fornitore. Non è né un'autorizzazione né una prova di purezza o sicurezza. Se un prodotto è legalmente qualificato come medicinale dipende dai criteri statutari e dalla sua presentazione effettiva, non solo da questa abbreviazione.","siehe":["arzneimittel","zulassung"],"seiten":["methodik.html"]},{"slug":"selank","begriff":"Selank","begriff_en":"Selank","kategorie":"wirkstoff","kurz":"Peptide sintetico investigato negli studi sui disturbi d'ansia.","kurz_en":"Peptide sintetico investigato negli studi sui disturbi d'ansia.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 18454096","titel_en":"PubMed: Pubblicazione di ricerca, PMID 18454096","url":"https://pubmed.ncbi.nlm.nih.gov/18454096/"}],"text":"Il paper clinico collegato confronta selank con medazepam nei disturbi d'ansia e nella neurastenia. Una singola pubblicazione non sostituisce né una valutazione completa delle evidenze né la verifica della qualità dei prodotti commercializzati.","text_en":"Il paper clinico collegato confronta selank con medazepam nei disturbi d'ansia e nella neurastenia. Una singola pubblicazione non sostituisce né una valutazione completa delle evidenze né la verifica della qualità dei prodotti commercializzati.","link":"wirkstoffe/selank.html"},{"slug":"semaglutid","begriff":"Semaglutide","begriff_en":"Semaglutide","kategorie":"wirkstoff","kurz":"Analogo GLP-1 con ricerca clinica e medicinali autorizzati.","kurz_en":"Analogo GLP-1 con ricerca clinica e medicinali autorizzati.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 33567185","titel_en":"PubMed: Pubblicazione di ricerca, PMID 33567185","url":"https://pubmed.ncbi.nlm.nih.gov/33567185/"},{"titel":"EMA: Autorizzazione specifica del prodotto Ozempic","titel_en":"EMA: Autorizzazione specifica del prodotto Ozempic","url":"https://www.ema.europa.eu/en/medicines/human/EPAR/ozempic"}],"text":"Il paper clinico collegato investiga semaglutide negli adulti con sovrappeso o obesità. La valutazione dell'EMA riguarda il medicinale specifico Ozempic. Né lo studio né l'autorizzazione verificano un prodotto di ricerca in un negozio simile denominato.","text_en":"Il paper clinico collegato investiga semaglutide negli adulti con sovrappeso o obesità. La valutazione dell'EMA riguarda il medicinale specifico Ozempic. Né lo studio né l'autorizzazione verificano un prodotto di ricerca in un negozio simile denominato.","link":"wirkstoffe/semaglutid.html"},{"slug":"semax","begriff":"Semax","begriff_en":"Semax","kategorie":"wirkstoff","kurz":"Eptapeptide sintetico, studiato tra l'altro in modelli nel ratto.","kurz_en":"Eptapeptide sintetico, studiato tra l'altro in modelli nel ratto.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 14556513","titel_en":"PubMed: Pubblicazione di ricerca, PMID 14556513","url":"https://pubmed.ncbi.nlm.nih.gov/14556513/"}],"text":"La pubblicazione citata indaga il BDNF in diverse regioni cerebrali dei ratti. Questi sono dati preclinici. Non stabiliscono un miglioramento cognitivo negli esseri umani.","text_en":"La pubblicazione citata indaga il BDNF in diverse regioni cerebrali dei ratti. Questi sono dati preclinici. Non stabiliscono un miglioramento cognitivo negli esseri umani.","link":"wirkstoffe/semax.html"},{"slug":"sequenz","begriff":"Sequenza","begriff_en":"Sequenza","kategorie":"grundlagen","kurz":"L'ordine fisso degli amminoacidi in una catena peptidica o proteica.","kurz_en":"L'ordine fisso degli amminoacidi in una catena peptidica o proteica.","quellen":[{"titel":"Alberts et al.: Struttura proteica","titel_en":"Alberts et al.: Struttura proteica","url":"https://www.ncbi.nlm.nih.gov/books/NBK26830/"}],"text":"La sequenza descrive l'ordine in cui gli amminoacidi individuali sono collegati tramite legami peptidici. Viene generalmente scritta utilizzando codici standardizzati di una o tre lettere per amminoacido. Due peptidi fatti degli stessi amminoacidi ma in un ordine diverso contano come molecole diverse, il che rende la sequenza un marcatore di identità chiave.","text_en":"La sequenza descrive l'ordine in cui gli amminoacidi individuali sono collegati tramite legami peptidici. Viene generalmente scritta utilizzando codici standardizzati di una o tre lettere per amminoacido. Due peptidi fatti degli stessi amminoacidi ma in un ordine diverso contano come molecole diverse, il che rende la sequenza un marcatore di identità chiave.","synonyme":["Sequenza di amminoacidi"],"synonyme_en":["Sequenza di amminoacidi"],"siehe":["aminosaeure","peptidbindung","identitaet"]},{"slug":"sermorelin","begriff":"Sermorelina","begriff_en":"Sermorelina","kategorie":"wirkstoff","kurz":"Peptide derivato da GHRH investigato nella ricerca endocrina.","kurz_en":"Peptide derivato da GHRH investigato nella ricerca endocrina.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 18031173","titel_en":"PubMed: Pubblicazione di ricerca, PMID 18031173","url":"https://pubmed.ncbi.nlm.nih.gov/18031173/"}],"text":"La revisione collegata colloca la sermorelina nella ricerca storica sulla carenza di ormone della crescita nell'infanzia. La letteratura medica storica non stabilisce né lo stato di autorizzazione attuale né la qualità di un prodotto commerciale.","text_en":"La revisione collegata colloca la sermorelina nella ricerca storica sulla carenza di ormone della crescita nell'infanzia. La letteratura medica storica non stabilisce né lo stato di autorizzazione attuale né la qualità di un prodotto commerciale.","synonyme":["GRF 1-29","GHRH(1-29)","Geref (nome commerciale storico)"],"synonyme_en":["GRF 1-29","GHRH(1-29)","Geref (nome commerciale storico)"],"link":"wirkstoffe/sermorelin.html"},{"slug":"ss-31","begriff":"SS-31 (elamipretide)","begriff_en":"SS-31 (elamipretide)","kategorie":"wirkstoff","kurz":"Elamipretide, un peptide sintetico investigato in studi sui disturbi mitocondriali.","kurz_en":"Elamipretide, un peptide sintetico investigato in studi sui disturbi mitocondriali.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 37268435","titel_en":"PubMed: Pubblicazione di ricerca, PMID 37268435","url":"https://pubmed.ncbi.nlm.nih.gov/37268435/"},{"titel":"FDA: Forzinity, approvato il 19 settembre 2025","titel_en":"FDA: Forzinity, approvato il 19 settembre 2025","url":"https://www.fda.gov/drugs/drug-trials-snapshots/drug-trials-snapshots-forzinity"}],"text":"Il 19 settembre 2025, la FDA ha concesso l'approvazione accelerata a Forzinity, contenente elamipretide, per un gruppo di pazienti definito con sindrome di Barth. Questa approvazione del prodotto statunitense non si applica ai prodotti chimici di ricerca venduti come SS-31.","text_en":"Il 19 settembre 2025, la FDA ha concesso l'approvazione accelerata a Forzinity, contenente elamipretide, per un gruppo di pazienti definito con sindrome di Barth. Questa approvazione del prodotto statunitense non si applica ai prodotti chimici di ricerca venduti come SS-31.","synonyme":["Elamipretide","MTP-131","Bendavia"],"synonyme_en":["Elamipretide","MTP-131","Bendavia"],"link":"wirkstoffe/ss-31.html"},{"slug":"steriles-wasser","begriff":"Acqua sterile","begriff_en":"Acqua sterile","kategorie":"handhabung","kurz":"Acqua per cui la sterilità è una caratteristica di prodotto specificata.","kurz_en":"Acqua per cui la sterilità è una caratteristica di prodotto specificata.","quellen":[{"titel":"FDA: Sterilità ed endotossine","titel_en":"FDA: Sterilità ed endotossine","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/inspection-technical-guides/bacterial-endotoxinspyrogens"}],"text":"Sterilità e assenza di endotossine sono proprietà diverse. I prodotti devono essere valutati rispetto alle loro specifiche; la parola “sterile” non implica né idoneità universale come solvente né una particolare durata di conservazione dopo l'apertura.","text_en":"Sterilità e assenza di endotossine sono proprietà diverse. I prodotti devono essere valutati rispetto alle loro specifiche; la parola “sterile” non implica né idoneità universale come solvente né una particolare durata di conservazione dopo l'apertura.","siehe":["bakteriostatisches-wasser","rekonstitution","sterilitaet"]},{"slug":"sterilitaet","begriff":"Sterilità","begriff_en":"Sterilità","kategorie":"labor","kurz":"La sterilità descrive l'assenza di microrganismi vivi in un campione, verificata tramite il proprio test di laboratorio dedicato.","kurz_en":"La sterilità descrive l'assenza di microrganismi vivi in un campione, verificata tramite il proprio test di laboratorio dedicato.","quellen":[{"titel":"FDA: Test di sterilità e controlli di processo","titel_en":"FDA: Test di sterilità e controlli di processo","url":"https://www.fda.gov/drugs/guidances-drugs/questions-and-answers-current-good-manufacturing-practice-regulations-production-and-process"}],"text":"Il test è indipendente dalla purezza, identità e valore di endotossina, ed è documentato separatamente. È principalmente rilevante per i peptidi liofilizzati che vengono disciolti e gestiti ulteriormente in un ambiente di laboratorio.","text_en":"Il test è indipendente dalla purezza, identità e valore di endotossina, ed è documentato separatamente. È principalmente rilevante per i peptidi liofilizzati che vengono disciolti e gestiti ulteriormente in un ambiente di laboratorio.","siehe":["endotoxin","coa"]},{"slug":"confounder","begriff":"Fattore di confondimento (confounder)","begriff_en":"Fattore di confondimento (confounder)","kategorie":"studien","kurz":"Fattore legato sia all'esito sia alla caratteristica studiata che può distorcere o simulare un'associazione.","kurz_en":"Fattore legato sia all'esito sia alla caratteristica studiata che può distorcere o simulare un'associazione.","quellen":[{"titel":"NLM MeSH: Confounding Factors, Epidemiologic","titel_en":"NLM MeSH: Confounding Factors, Epidemiologic","url":"https://www.ncbi.nlm.nih.gov/mesh/68015986"}],"text":"Un fattore di confondimento può causare o prevenire l'esito di interesse senza essere un passaggio intermedio della caratteristica studiata. È anche collegato a tale caratteristica e può distorcere un'associazione o crearne una. Esempio: chi beve caffè fuma in media più spesso, quindi una malattia polmonare potrebbe essere attribuita erroneamente al caffè. Gli studi tengono conto dei fattori di confondimento tramite assegnazione casuale o aggiustamento statistico.","text_en":"Un fattore di confondimento può causare o prevenire l'esito di interesse senza essere un passaggio intermedio della caratteristica studiata. È anche collegato a tale caratteristica e può distorcere un'associazione o crearne una. Esempio: chi beve caffè fuma in media più spesso, quindi una malattia polmonare potrebbe essere attribuita erroneamente al caffè. Gli studi tengono conto dei fattori di confondimento tramite assegnazione casuale o aggiustamento statistico.","synonyme":["Fattore di confondimento","Variabile di confondimento"],"synonyme_en":["Fattore di confondimento","Variabile di confondimento"],"siehe":["association","observational-study","rct"],"seiten":["studien.html"]},{"slug":"studienphasen","begriff":"Fasi degli studi","begriff_en":"Fasi degli studi","kategorie":"studien","kurz":"Le quattro fasi dei test clinici: fasi I a III prima dell'approvazione, fase IV successivamente nell'uso quotidiano.","kurz_en":"Le quattro fasi dei test clinici: fasi I a III prima dell'approvazione, fase IV successivamente nell'uso quotidiano.","quellen":[{"titel":"FDA: Fasi della ricerca clinica","titel_en":"FDA: Fasi della ricerca clinica","url":"https://www.fda.gov/patients/drug-development-process/step-3-clinical-research"}],"text":"Lo sviluppo clinico è spesso descritto in quattro fasi: Fase I investiga principalmente la sicurezza e la tollerabilità in volontari sani o pazienti. Fase II esamina le evidenze iniziali di efficacia e ulteriori domande sulla sicurezza. Fase III investiga queste in gruppi più ampi. Fase IV copre gli studi dopo l'approvazione. La fase da sola non stabilisce la qualità di uno studio individuale.","text_en":"Lo sviluppo clinico è spesso descritto in quattro fasi: Fase I investiga principalmente la sicurezza e la tollerabilità in volontari sani o pazienti. Fase II esamina le evidenze iniziali di efficacia e ulteriori domande sulla sicurezza. Fase III investiga queste in gruppi più ampi. Fase IV copre gli studi dopo l'approvazione. La fase da sola non stabilisce la qualità di uno studio individuale.","synonyme":["Fasi I a IV"],"synonyme_en":["Fasi I a IV"],"siehe":["klinische-studie","rct"],"seiten":["studien.html"]},{"slug":"survodutid","begriff":"Survodutide","begriff_en":"Survodutide","kategorie":"wirkstoff","kurz":"Agonista duale del glucagone e del recettore GLP-1 investigato in studi clinici.","kurz_en":"Agonista duale del glucagone e del recettore GLP-1 investigato in studi clinici.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 38330987","titel_en":"PubMed: Pubblicazione di ricerca, PMID 38330987","url":"https://pubmed.ncbi.nlm.nih.gov/38330987/"}],"text":"Lo studio di fase II collegato investiga il survodutide come agonista recettoriale duale. I dati dello studio riguardano la formulazione e la popolazione testate e non verificano la qualità dei prodotti chimici di ricerca.","text_en":"Lo studio di fase II collegato investiga il survodutide come agonista recettoriale duale. I dati dello studio riguardano la formulazione e la popolazione testate e non verificano la qualità dei prodotti chimici di ricerca.","synonyme":["BI 456906"],"synonyme_en":["BI 456906"],"link":"wirkstoffe/survodutid.html"},{"slug":"tb-500","begriff":"TB-500","begriff_en":"TB-500","kategorie":"wirkstoff","kurz":"Un nome utilizzato in un articolo analitico originale per un frammento acetilato di timosina beta-4.","kurz_en":"Un nome utilizzato in un articolo analitico originale per un frammento acetilato di timosina beta-4.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 23084823","titel_en":"PubMed: Pubblicazione di ricerca, PMID 23084823","url":"https://pubmed.ncbi.nlm.nih.gov/23084823/"}],"text":"L'articolo analitico collegato identifica un frammento acetilato in un prodotto etichettato TB-500. I risultati per la timosina beta-4 a lunghezza intera non si applicano automaticamente a questo frammento o ad altri prodotti commercializzati.","text_en":"L'articolo analitico collegato identifica un frammento acetilato in un prodotto etichettato TB-500. I risultati per la timosina beta-4 a lunghezza intera non si applicano automaticamente a questo frammento o ad altri prodotti commercializzati.","synonyme":["Frammento di timosina beta-4","TB4 Frag"],"synonyme_en":["Frammento di timosina beta-4","TB4 Frag"],"link":"wirkstoffe/tb-500.html"},{"slug":"tesamorelin","begriff":"Tesamorelina","begriff_en":"Tesamorelina","kategorie":"wirkstoff","kurz":"Analogo del fattore di rilascio dell'ormone della crescita sintetico investigato in studi clinici.","kurz_en":"Analogo del fattore di rilascio dell'ormone della crescita sintetico investigato in studi clinici.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 18057338","titel_en":"PubMed: Pubblicazione di ricerca, PMID 18057338","url":"https://pubmed.ncbi.nlm.nih.gov/18057338/"}],"text":"Il paper clinico citato investiga un fattore di rilascio dell'ormone della crescita in persone con HIV. Il contesto clinico e la preparazione dello studio limitano come i risultati possano essere generalizzati.","text_en":"Il paper clinico citato investiga un fattore di rilascio dell'ormone della crescita in persone con HIV. Il contesto clinico e la preparazione dello studio limitano come i risultati possano essere generalizzati.","synonyme":["Egrifta","TH9507","Egrifta WR"],"synonyme_en":["Egrifta","TH9507","Egrifta WR"],"link":"wirkstoffe/tesamorelin.html"},{"slug":"thymosin-alpha-1","begriff":"Timosina alfa 1","begriff_en":"Timosina alfa 1","kategorie":"wirkstoff","kurz":"Peptide dal sistema timosina investigato in studi clinici e preclinici.","kurz_en":"Peptide dal sistema timosina investigato in studi clinici e preclinici.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 3998766","titel_en":"PubMed: Pubblicazione di ricerca, PMID 3998766","url":"https://pubmed.ncbi.nlm.nih.gov/3998766/"}],"text":"Lo studio randomizzato collegato investiga la timosina alfa-1 sintetica in un particolare contesto oncologico. Tale risultato non è una prova generale di potenziamento immunitario e non verifica i prodotti di ricerca commercializzati liberamente.","text_en":"Lo studio randomizzato collegato investiga la timosina alfa-1 sintetica in un particolare contesto oncologico. Tale risultato non è una prova generale di potenziamento immunitario e non verifica i prodotti di ricerca commercializzati liberamente.","synonyme":["Tα1","Zadaxin (nome commerciale)"],"synonyme_en":["Tα1","Zadaxin (nome commerciale)"],"link":"wirkstoffe/thymosin-alpha-1.html"},{"slug":"thymosine","begriff":"Timosine","begriff_en":"Timosine","kategorie":"klassen","kurz":"Le timosine sono una famiglia di peptidi originariamente isolati dalla ghiandola del timo.","kurz_en":"Le timosine sono una famiglia di peptidi originariamente isolati dalla ghiandola del timo.","quellen":[{"titel":"NCI: Timosine","titel_en":"NCI: Timosine","url":"https://www.cancer.gov/publications/dictionaries/cancer-drug/def/recombinant-thymosin"}],"text":"Il nome copre diversi peptidi originariamente isolati da materiale timico. Timosine alfa e beta differiscono per struttura e contesto di ricerca. I risultati per una timosina non si applicano automaticamente alle altre.","text_en":"Il nome copre diversi peptidi originariamente isolati da materiale timico. Timosine alfa e beta differiscono per struttura e contesto di ricerca. I risultati per una timosina non si applicano automaticamente alle altre.","synonyme":["Peptidi di timosina"],"synonyme_en":["Peptidi di timosina"],"siehe":["peptidhormon","protein"],"wirkstoffe":["thymosin-alpha-1","tb-500"],"seiten":["peptid-1x1.html"]},{"slug":"tiermodell","begriff":"Modello animale","begriff_en":"Modello animale","kategorie":"studien","kurz":"Un animale di laboratorio, come un topo o un ratto, utilizzato per studiare una sostanza in vivo. Non prova diretta per gli esseri umani.","kurz_en":"Un animale di laboratorio, come un topo o un ratto, utilizzato per studiare una sostanza in vivo. Non prova diretta per gli esseri umani.","quellen":[{"titel":"NCI: modello animale","titel_en":"NCI: modello animale","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/animal-model"}],"text":"Un modello animale è un animale di laboratorio come un topo, un ratto o un pesce zebra in cui viene studiato il metabolismo, il comportamento o il tessuto in condizioni controllate. Serve alla ricerca preclinica prima di un possibile studio clinico. Poiché genetica e fisiologia differiscono, un effetto in un modello animale non è prova di un effetto negli esseri umani.","text_en":"Un modello animale è un animale di laboratorio come un topo, un ratto o un pesce zebra in cui viene studiato il metabolismo, il comportamento o il tessuto in condizioni controllate. Serve alla ricerca preclinica prima di un possibile studio clinico. Poiché genetica e fisiologia differiscono, un effetto in un modello animale non è prova di un effetto negli esseri umani.","siehe":["in-vivo","praeklinisch"],"seiten":["studien.html"]},{"slug":"tirzepatid","begriff":"Tirzepatide","begriff_en":"Tirzepatide","kategorie":"wirkstoff","kurz":"Agonisti del recettore del GIP e del GLP-1 doppi studiati in studi clinici.","kurz_en":"Agonisti del recettore del GIP e del GLP-1 doppi studiati in studi clinici.","quellen":[{"titel":"PubMed: Pubblicazione di ricerca, PMID 35658024","titel_en":"PubMed: Pubblicazione di ricerca, PMID 35658024","url":"https://pubmed.ncbi.nlm.nih.gov/35658024/"}],"text":"Lo studio clinico randomizzato collegato investiga la tirzepatide nell'obesità. La formulazione dello studio e i controlli di qualità devono essere distinti dai prodotti chimici di ricerca commercializzati liberamente.","text_en":"Lo studio clinico randomizzato collegato investiga la tirzepatide nell'obesità. La formulazione dello studio e i controlli di qualità devono essere distinti dai prodotti chimici di ricerca commercializzati liberamente.","synonyme":["LY3298176"],"synonyme_en":["LY3298176"],"link":"wirkstoffe/tirzepatid.html"},{"slug":"u-100","begriff":"U-100","begriff_en":"U-100","kategorie":"handhabung","kurz":"Designazione per insulina contenente 100 unità per millilitro, non un'unità di peptide generale.","kurz_en":"Designazione per insulina contenente 100 unità per millilitro, non un'unità di peptide generale.","quellen":[{"titel":"DailyMed: Significato della designazione U-100","titel_en":"DailyMed: Significato della designazione U-100","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c8ecbd7a-0e22-4fc7-a503-faa58c1b6f3f"}],"text":"U-100 è una designazione di concentrazione per i prodotti insulinici. Non è un'unità generale di massa di peptide. Una scala etichettata in questo modo non può essere interpretata come quantità di peptide senza conoscere la sostanza e la sua specifica.","text_en":"U-100 è una designazione di concentrazione per i prodotti insulinici. Non è un'unità generale di massa di peptide. Una scala etichettata in questo modo non può essere interpretata come quantità di peptide senza conoscere la sostanza e la sua specifica.","siehe":["internationale-einheit","konzentration"]},{"slug":"vial","begriff":"Flacone","begriff_en":"Flacone","kategorie":"handhabung","kurz":"Un viale è un piccolo contenitore di vetro, solitamente sigillato con un tappo di gomma, che contiene un peptide sotto forma di polvere o soluzione.","kurz_en":"Un viale è un piccolo contenitore di vetro, solitamente sigillato con un tappo di gomma, che contiene un peptide sotto forma di polvere o soluzione.","quellen":[{"titel":"ICH Q7: Produzione, lotti e certificati di analisi","titel_en":"ICH Q7: Produzione, lotti e certificati di analisi","url":"https://www.fda.gov/media/71518/download"}],"text":"I viali sono l'imballaggio standard per i peptidi liofilizzati nel commercio di ricerca. Il tappo di gomma consente un prelievo chiuso e l'etichetta stampata riporta solitamente il numero di lotto e la quantità. Un singolo viale può essere abbinato a un CoA purché il numero di lotto corrisponda.","text_en":"I viali sono l'imballaggio standard per i peptidi liofilizzati nel commercio di ricerca. Il tappo di gomma consente un prelievo chiuso e l'etichetta stampata riporta solitamente il numero di lotto e la quantità. Un singolo viale può essere abbinato a un CoA purché il numero di lotto corrisponda.","synonyme":["Bottiglia piccola"],"synonyme_en":["Bottiglia piccola"],"siehe":["charge","lyophilisat","aliquot"]},{"slug":"wachstumshormon","begriff":"Ormone della crescita","begriff_en":"Ormone della crescita","kategorie":"klassen","kurz":"L'ormone della crescita è un ormone pituitario che regola la crescita, il metabolismo e la composizione corporea.","kurz_en":"L'ormone della crescita è un ormone pituitario che regola la crescita, il metabolismo e la composizione corporea.","quellen":[{"titel":"NIDDK: Ormone della crescita e IGF-1","titel_en":"NIDDK: Ormone della crescita e IGF-1","url":"https://www.niddk.nih.gov/health-information/endocrine-diseases/acromegaly"}],"langform":"Somatotropina","langform_en":"Somatotropina","text":"L'ormone della crescita, anche chiamato somatotropina o GH, è prodotto dalle cellule somatotrope nella ghiandola pituitaria e rilasciato nel sangue in pulsazioni, controllato da GHRH, somatostatina e grelina. Regola la crescita longitudinale, il metabolismo muscolare e adiposo e la densità ossea, sia direttamente che tramite IGF-1 dal fegato. Diverse classi di peptidi mirano a diversi punti lungo questo asse, inclusa il rilascio dalla ghiandola pituitaria anteriore.","text_en":"L'ormone della crescita, anche chiamato somatotropina o GH, è prodotto dalle cellule somatotrope nella ghiandola pituitaria e rilasciato nel sangue in pulsazioni, controllato da GHRH, somatostatina e grelina. Regola la crescita longitudinale, il metabolismo muscolare e adiposo e la densità ossea, sia direttamente che tramite IGF-1 dal fegato. Diverse classi di peptidi mirano a diversi punti lungo questo asse, inclusa il rilascio dalla ghiandola pituitaria anteriore.","synonyme":["GH","HGH","Somatotropina"],"synonyme_en":["GH","HGH","Somatotropina"],"siehe":["ghrh","ghrp","igf-1"],"wirkstoffe":["cjc-1295","tesamorelin","sermorelin","ipamorelin","hexarelin"],"seiten":["peptid-1x1.html"]},{"slug":"wada","begriff":"WADA","begriff_en":"WADA","kategorie":"recht","kurz":"WADA pubblica un elenco annuale di sostanze proibite per lo sport che include anche i peptidi.","kurz_en":"WADA pubblica un elenco annuale di sostanze proibite per lo sport che include anche i peptidi.","quellen":[{"titel":"WADA: Elenco attuale delle sostanze proibite","titel_en":"WADA: Elenco attuale delle sostanze proibite","url":"https://www.wada-ama.org/en/prohibited-list"}],"langform":"Agenzia Mondiale Antidoping","langform_en":"Agenzia Mondiale Antidoping","text":"L'Agenzia Mondiale Antidoping coordina le regole antidoping nello sport organizzato e aggiorna la sua lista di sostanze proibite annualmente. Diverse categorie coprono ormoni peptidici e sostanze correlate, indipendentemente dal loro status legale al di fuori dello sport. La sostanza specifica coperta è indicata solo nella lista WADA corrente.","text_en":"L'Agenzia Mondiale Antidoping coordina le regole antidoping nello sport organizzato e aggiorna la sua lista di sostanze proibite annualmente. Diverse categorie coprono ormoni peptidici e sostanze correlate, indipendentemente dal loro status legale al di fuori dello sport. La sostanza specifica coperta è indicata solo nella lista WADA corrente.","seiten":["faq.html"]},{"slug":"zulassung","begriff":"Autorizzazione all'immissione in commercio","begriff_en":"Autorizzazione all'immissione in commercio","kategorie":"recht","kurz":"L'autorizzazione all'immissione in commercio è l'approvazione normativa richiesta per vendere un medicinale in un mercato.","kurz_en":"L'autorizzazione all'immissione in commercio è l'approvazione normativa richiesta per vendere un medicinale in un mercato.","quellen":[{"titel":"EMA: Decisioni di valutazione e autorizzazione","titel_en":"EMA: Decisioni di valutazione e autorizzazione","url":"https://www.ema.europa.eu/en/about-us/what-we-do/authorisation-medicines/how-ema-evaluates-medicines-human-use"}],"text":"Nel procedimento centralizzato dell'UE, l'EMA valuta il fascicolo scientifico. La Commissione Europea concede l'autorizzazione all'immissione in commercio. L'autorizzazione si applica a un medicinale specifico in condizioni specificate, non a ogni prodotto che riporta lo stesso nome di sostanza.","text_en":"Nel procedimento centralizzato dell'UE, l'EMA valuta il fascicolo scientifico. La Commissione Europea concede l'autorizzazione all'immissione in commercio. L'autorizzazione si applica a un medicinale specifico in condizioni specificate, non a ogni prodotto che riporta lo stesso nome di sostanza.","synonyme":["Autorizzazione all'immissione in commercio"],"synonyme_en":["Autorizzazione all'immissione in commercio"],"siehe":["ema","fda","arzneimittel"],"seiten":["peptid-1x1.html"]}];
